import { recordDebugLog } from '../../../utils/helpers';
import { SyncError, ERROR_CODES } from '../errors';
import { throttle, debounce } from 'lodash-es';
import {
    getWindowTabsData,
    getSettingsData,
    getSiteConfigsData,
    getQuickAccessData,
    getRecentClosedTabsData
} from '../tasks';
import { getUserConfig } from '../../user';
import { calculateDataHash } from './crypto';
import { applyWindowTabs } from '../tasks/windowTabs';
import { applySettings } from '../tasks/settings';
import { applySiteConfigs } from '../tasks/siteConfigs';
import { applyQuickAccess } from '../tasks/quickAccess';
import { applyRecentClosedTabs } from '../tasks/recentClosedTabs';
import syncLock from '../../../utils/syncLock';

// Get local data for syncing
export async function getLocalData(dataKey, localCache) {
    recordDebugLog(`[syncService] [${dataKey}] Getting local data...`);
    try {
        const timestamp = await localCache.get(`${dataKey}_last_sync_at`);
        recordDebugLog(`[syncService] [${dataKey}] Last sync timestamp: ${timestamp}`, `${dataKey}_last_sync_at`);

        let items;
        switch (dataKey) {
            case 'windowTabs':
                items = await getWindowTabsData();
                break;
            case 'settings':
                items = await getSettingsData();
                break;
            case 'siteConfigs':
                items = await getSiteConfigsData();
                break;
            case 'quickAccess':
                items = await getQuickAccessData();
                break;
            case 'recentClosedTabs':
                items = await getRecentClosedTabsData();
                break;
            default:
                recordDebugLog(`[syncService][${dataKey}] Invalid data key`);
                return null;
        }

        if (!items) {
            recordDebugLog(`[syncService][${dataKey}] No local data found`);
            return null;
        }

        const hash = await calculateDataHash(dataKey, items);
        const deviceName = await getUserConfig('deviceName');
        recordDebugLog(`[syncService][${dataKey}] Got local data with hash: ${hash}`);

        return { items, timestamp, hash, deviceName };

    } catch (error) {
        recordDebugLog(`[syncService][${dataKey}] Failed to get local data: `, error);
        return null;
    }
}

// Apply synced data changes
export async function applyData(dataKey, localCache) {
    recordDebugLog(`[syncService][${dataKey}] Starting to apply data...`);
    try {
        switch (dataKey) {
            case 'windowTabs':
                await applyWindowTabs(dataKey, localCache);
                break;
            case 'settings':
                await applySettings(dataKey, localCache);
                break;
            case 'siteConfigs':
                await applySiteConfigs(dataKey, localCache);
                break;
            case 'quickAccess':
                await applyQuickAccess(dataKey, localCache);
                break;
            case 'recentClosedTabs':
                await applyRecentClosedTabs(dataKey, localCache);
                break;
            default:
                recordDebugLog(`[syncService][${dataKey}] No apply function found`);
                return;
        }
        recordDebugLog(`[syncService][${dataKey}] Successfully applied data`);
    } catch (error) {
        recordDebugLog(`[syncService][${dataKey}] Failed to apply data: `, error);
        throw error;
    }
}

// Manage throttled/debounced apply functions
function getOrCreateDeferredApply(dataKey) {
    const delay = dataKey === 'windowTabs' ? 2000 : 1000;
    const action = 'apply';
    const type = dataKey === 'windowTabs' ? 'throttle' : 'debounce';

    return (localCache) => {
        return syncLock.getDeferredFn(
            dataKey,
            action,
            () => applyData(dataKey, localCache),
            delay,
            type
        )();
    };
}

// Save data to local storage
export async function saveLocalData(localCache, dataKey, distData, shouldApply = false) {
    recordDebugLog(`[syncService][${dataKey}] Saving local data...`);
    recordDebugLog(`[syncService][${dataKey}] Data to save: `, distData);
    recordDebugLog(`[syncService][${dataKey}] Should apply: ${shouldApply}`);

    try {
        const dataToSave = {
            items: distData.items || distData,
            timestamp: distData.timestamp || Date.now(),
            hash: distData.hash,
            deviceName: distData.deviceName
        };

        await localCache.set(dataKey, dataToSave);

        if (dataToSave.hash) {
            await localCache.set(`${dataKey}_local_hash`, dataToSave.hash);
        }

        recordDebugLog(`[syncService][${dataKey}] Data saved to local cache`);

        if (shouldApply) {
            recordDebugLog(`[syncService][${dataKey}] Applying data`);
            const deferredApply = getOrCreateDeferredApply(dataKey);
            await deferredApply(localCache);
        }

    } catch (error) {
        recordDebugLog(`[syncService][${dataKey}] Error saving local data: `, error);
        throw new SyncError(
            ERROR_CODES.STORAGE_WRITE_ERROR,
            {
                dataType: dataKey,
                message: error.message
            },
            error
        );
    }
}

