import { recordDebugLog } from "../../../utils/helpers";

// Improved Chrome API triggers with better debouncing
export function setupWindowTabsTriggers(syncCallback, config) {
    const handleWindowEvent = async () => {
        if (config.skipLastWindow) {
            const windows = await chrome.windows.getAll({ windowTypes: ['normal'] });
            if (windows.length === 0) {
                return;
            }
        }

        // Check total number of tabs
        const tabs = await chrome.tabs.query({});
        if (tabs.length === 0) {
            return;
        }

        syncCallback('windowTabs');
    };

    const handleTabEvent = () => {
        syncCallback('windowTabs');
    };

    // Group all window events
    chrome.windows.onCreated.addListener(async (window) => {
        await handleWindowEvent('created', window);
    });

    chrome.windows.onRemoved.addListener(async (windowId) => {
        try {
            const window = await chrome.windows.get(windowId, { windowTypes: ['normal'] });
            await handleWindowEvent('removed', window);
        } catch (error) {
            // 忽略错误，可能窗口已经不存在
            return;
        }
    });

    // Tab event listeners
    chrome.tabs.onCreated.addListener(async (tab) => {
        if (!tab.url?.startsWith('http')) {
            return;
        }
        await handleTabEvent('created');
    });

    chrome.tabs.onUpdated.addListener(async (tabId, changeInfo, tab) => {
        if (!tab.url?.startsWith('http')) {
            return;
        }
        if (changeInfo.status === 'complete' ||
            changeInfo.pinned !== undefined ||
            changeInfo.groupId !== undefined) {
            await handleTabEvent('updated', { tabId, changeInfo });
        }
    });


    chrome.tabs.onRemoved.addListener(async (tabId, removeInfo) => {
        await handleTabEvent('removed');
    });

    // Tab groups event listeners
    if (chrome.tabGroups) {
        chrome.tabGroups.onCreated.addListener(async () => await handleTabEvent('created'));
        chrome.tabGroups.onUpdated.addListener(async () => await handleTabEvent('updated'));
        chrome.tabGroups.onRemoved.addListener(async () => await handleTabEvent('removed'));
    }

    // Return cleanup function
    return () => {
        // Remove event listeners
        chrome.windows.onCreated.removeListener(handleWindowEvent);
        chrome.windows.onRemoved.removeListener(handleWindowEvent);
        chrome.tabs.onCreated.removeListener(handleTabEvent);
        chrome.tabs.onUpdated.removeListener(handleTabEvent);
        chrome.tabs.onRemoved.removeListener(handleTabEvent);

        if (chrome.tabGroups) {
            chrome.tabGroups.onCreated.removeListener(handleTabEvent);
            chrome.tabGroups.onUpdated.removeListener(handleTabEvent);
            chrome.tabGroups.onRemoved.removeListener(handleTabEvent);
        }
    };
}

export function setupRecentClosedTabsTriggers(syncCallback, config) {
    const handleTabClose = () => {
        syncCallback('recentClosedTabs');
    };

    const handleWindowClose = (windowId) => {
        // 窗口已关闭，直接触发同步
        recordDebugLog(`[syncService] Window removed - triggering sync for recent closed tabs`);
        syncCallback('recentClosedTabs');
    };

    // Add event listeners
    chrome.tabs.onRemoved.addListener(handleTabClose);
    chrome.windows.onRemoved.addListener(handleWindowClose);

    // Return cleanup function
    return () => {
        chrome.tabs.onRemoved.removeListener(handleTabClose);
        chrome.windows.onRemoved.removeListener(handleWindowClose);
    };
}