import pako from 'pako';
import { encryptData, decryptData } from '../../user';
import { recordDebugLog } from '../../../utils/helpers';
import { SyncError, ERROR_CODES } from '../errors';

export async function processData(data, type) {
    recordDebugLog(`Processing data (${type})...`);
    try {
        if (type === 'compress') {
            recordDebugLog('Compressing data...');
            const jsonString = await encryptData(data);
            const compressed = pako.deflate(jsonString, { to: 'uint8array' });
            recordDebugLog('Data compressed successfully');
            return new Blob([compressed], { type: 'application/octet-stream' });
        } else {
            recordDebugLog('Decompressing data...');
            const arrayBuffer = await data.arrayBuffer();
            const inflated = pako.inflate(new Uint8Array(arrayBuffer));
            const jsonString = new TextDecoder().decode(inflated);
            const decrypted = await decryptData(jsonString);
            recordDebugLog('Data decompressed successfully');
            return decrypted;
        }
    } catch (error) {
        recordDebugLog(`Error processing data (${type}):`, error);
        const errorCode = type === 'compress' ?
            ERROR_CODES.PROCESS_COMPRESS_ERROR :
            ERROR_CODES.PROCESS_DECOMPRESS_ERROR;

        throw new SyncError(errorCode, {
            message: error.message
        }, error);
    }
} 