import React, { useState, useRef } from "react";
import { userStore } from "../../../../core/stores/userStore";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import { Grid, Typography, FormControlLabel, Switch, Button, Dialog, DialogActions, DialogContent, DialogTitle, Box, Paper, IconButton, Stack, Divider, Card } from "@mui/material";
import { sendRuntimeMessage } from "../../../../core/browers/runtime";
import { DndContext, closestCenter, MouseSensor, TouchSensor, useSensor, useSensors, useDroppable, DragOverlay, pointerWithin } from '@dnd-kit/core';
import { SortableContext, horizontalListSortingStrategy, rectSortingStrategy, useSortable } from '@dnd-kit/sortable';
import { CSS } from '@dnd-kit/utilities';
import { ArrowRight, Close, Add, DragIndicator } from "@mui/icons-material";
import { toast } from "react-toastify";

export default function ShowToolbar() {
    const { t } = useTranslationContext("options", { keyPrefix: "settings.appearance.toolbar" });

    const { updateSetting, showToolbar, toolbarOptions } = userStore((state) => ({
        updateSetting: state.updateSetting,
        showToolbar: state.settings.showToolbar,
        toolbarOptions: state.settings.toolbarOptions
    }));

    const [open, setOpen] = useState(false);
    const leftAreaRef = useRef(null);
    const rightAreaRef = useRef(null);
    const [activeId, setActiveId] = useState(null);
    const [activeName, setActiveName] = useState(null);
    const [activeShowLabel, setActiveShowLabel] = useState(null);

    const handleShowToolbarChange = async (event) => {
        const { checked } = event.target;
        await updateSetting('showToolbar', checked);
        await sendRuntimeMessage("update_setting", { key: "showToolbar", value: checked });
    };

    const handleOptionShowLabelChange = async (event) => {
        const { checked } = event.target;
        const newToolbarOptions = { ...toolbarOptions, showLabel: checked };
        await updateSetting('toolbarOptions', newToolbarOptions);
        await sendRuntimeMessage("update_setting", { key: "toolbarOptions", value: newToolbarOptions });
    };

    const handleOpen = () => setOpen(true);
    const handleClose = () => setOpen(false);

    const handleDragStart = (event) => {
        const { active } = event;
        const activeNav = toolbarOptions.navs.find(nav => nav.id === active.id);
        if (activeNav) {
            setActiveId(active.id);
            setActiveName(activeNav.name);
            setActiveShowLabel(activeNav.showLabel);
        }
    };

    const handleDragEnd = async (event) => {
        const { active, over } = event;

        setActiveId(null);
        setActiveName(null);
        setActiveShowLabel(null);

        if (!active?.id || !over?.id) return;

        let newNavs = [...toolbarOptions.navs];
        const activeNav = newNavs.find(item => item.id === active.id);
        if (!activeNav) return;

        // 确定目标区域
        const targetId = over.data?.current?.sortable?.containerId || over.id;
        const isLeftArea = targetId === 'left';
        const isRightArea = targetId === 'right';

        // 更新对齐方式
        if (isLeftArea || isRightArea) {
            const newAlign = isLeftArea ? 'flex-start' : 'flex-end';
            if (activeNav.align !== newAlign) {
                newNavs = newNavs.map(item =>
                    item.id === active.id ? { ...item, align: newAlign } : item
                );
            }
        }

        // 分别获取左右区域的导航项
        const leftNavs = newNavs
            .filter(nav => nav.enable && nav.align === 'flex-start')
            .sort((a, b) => a.sort - b.sort);
        const rightNavs = newNavs
            .filter(nav => nav.enable && nav.align === 'flex-end')
            .sort((a, b) => a.sort - b.sort);

        const targetNavs = isLeftArea || activeNav.align === 'flex-start' ? leftNavs : rightNavs;
        const activeIndex = targetNavs.findIndex(nav => nav.id === active.id);
        const overIndex = isLeftArea || isRightArea
            ? targetNavs.length
            : targetNavs.findIndex(nav => nav.id === over.id);

        if (activeIndex !== -1 && overIndex !== -1 && activeIndex !== overIndex) {
            const newSort = [...targetNavs];
            const [movedItem] = newSort.splice(activeIndex, 1);
            newSort.splice(overIndex, 0, movedItem);

            // 分别更新左右区域的排序值
            if (isLeftArea || activeNav.align === 'flex-start') {
                newSort.forEach((nav, index) => {
                    const navIndex = newNavs.findIndex(item => item.id === nav.id);
                    if (navIndex !== -1) {
                        newNavs[navIndex] = { ...newNavs[navIndex], sort: index + 1 };
                    }
                });
            } else {
                newSort.forEach((nav, index) => {
                    const navIndex = newNavs.findIndex(item => item.id === nav.id);
                    if (navIndex !== -1) {
                        newNavs[navIndex] = { ...newNavs[navIndex], sort: index + 1 };
                    }
                });
            }
        }

        const newOptions = { ...toolbarOptions, navs: newNavs };
        await updateSetting('toolbarOptions', newOptions);
        await sendRuntimeMessage("update_setting", { key: "toolbarOptions", value: newOptions });
    };

    const handleEnable = async (id) => {
        const newNavs = toolbarOptions.navs.map((item) =>
            item.id === id ? { ...item, enable: true, align: 'flex-start' } : item
        );
        const newOptions = { ...toolbarOptions, navs: newNavs };
        await updateSetting('toolbarOptions', newOptions);
        await sendRuntimeMessage("update_setting", { key: "toolbarOptions", value: newOptions });
    };

    const handleSwitchLabel = async (id) => {
        const newNavs = toolbarOptions.navs.map((item) =>
            item.id === id ? { ...item, showLabel: !item.showLabel } : item
        );
        const newOptions = { ...toolbarOptions, navs: newNavs };
        await updateSetting('toolbarOptions', newOptions);
        await sendRuntimeMessage("update_setting", { key: "toolbarOptions", value: newOptions });
    };

    const handleDelete = async (id) => {
        const curNav = toolbarOptions.navs.find((item) => item.id === id);
        if (curNav?.name === 'version') {
            try {
                const { isOnToolbar } = await chrome.action.getUserSettings();
                if (!isOnToolbar) {
                    toast(t('pinToToolbarReminder'));
                    return;
                }
            } catch (error) {
                console.error("Error checking toolbar settings:", error);
                return;
            }
        }

        const newNavs = toolbarOptions.navs.map((item) =>
            item.id === id ? { ...item, enable: false } : item
        );
        const newOptions = { ...toolbarOptions, navs: newNavs };
        await updateSetting('toolbarOptions', newOptions);
        await sendRuntimeMessage("update_setting", { key: "toolbarOptions", value: newOptions });
    };

    const DraggableItem = ({ id, name, showLabel }) => {
        const {
            attributes,
            listeners,
            setNodeRef,
            transform,
            transition,
            isDragging
        } = useSortable({
            id: id,
            data: {
                type: 'item',
                id: id
            }
        });

        const style = {
            opacity: isDragging ? 0.5 : 1,
            touchAction: 'none',
            transform: CSS.Transform.toString(transform),
            transition
        };

        return (
            <Card
                ref={setNodeRef}
                sx={{ border: "1px solid #e0e0e0", borderRadius: 2, p: 2, display: 'flex', alignItems: 'center', boxShadow: 3, position: "relative" }}
                style={style}
            >
                <IconButton
                    size="small"
                    onClick={(e) => {
                        e.stopPropagation();
                        handleDelete(id);
                    }}
                    sx={{ position: 'absolute', top: 0, right: 0 }}
                >
                    <Close color="error" fontSize="small" />
                </IconButton>
                <IconButton
                    size="small"
                    sx={{ position: 'absolute', top: 0, left: 0, cursor: 'move' }}
                    {...attributes}
                    {...listeners}
                >
                    <DragIndicator color="action" fontSize="small" />
                </IconButton>
                <Stack direction="column" spacing={2} useFlexGap sx={{ padding: '5px' }} >
                    <Typography
                        variant="h4"
                        color="error"
                        size="small"
                    >
                        {t(name)}
                    </Typography>
                    <FormControlLabel
                        control={
                            <Switch
                                size="small"
                                color="error"
                                disabled={!toolbarOptions.showLabel}
                                checked={showLabel && toolbarOptions.showLabel}
                                onChange={() => handleSwitchLabel(id)}
                                name='showLabel'
                            />
                        }
                        label={t('showLabel')}
                    />
                </Stack>
            </Card>
        );
    };

    const DroppableArea = ({ id, children }) => {
        const { setNodeRef } = useDroppable({
            id: id
        });

        const items = toolbarOptions.navs
            .filter(option => option.enable && option.align === (id === 'left' ? 'flex-start' : 'flex-end'))
            .sort((a, b) => a.sort - b.sort)
            .map(option => option.id);

        return (
            <Box ref={setNodeRef} sx={{ minHeight: '100px' }}>
                <SortableContext items={items} strategy={rectSortingStrategy}>
                    {children}
                </SortableContext>
            </Box>
        );
    };

    const sensors = useSensors(
        useSensor(MouseSensor, {
            activationConstraint: {
                distance: 10,
                delay: 100,
                tolerance: 5
            }
        }),
        useSensor(TouchSensor, {
            activationConstraint: {
                delay: 100,
                tolerance: 5
            }
        })
    );

    return (
        <Grid container alignItems="center" >
            <Grid item xs={8}>
                <Typography variant="h3" mb={1}>{t("label")}</Typography>
                <Typography variant="body1" color='text.secondary'>{t("description")} </Typography>
            </Grid>
            <Grid item xs={2}>
                <FormControlLabel control={<Switch color="error" checked={showToolbar}
                    onChange={handleShowToolbarChange} />}
                    labelPlacement="start"
                />
            </Grid>
            {showToolbar &&
                <Grid item xs={2}>
                    <Button size="small" endIcon={<ArrowRight />} variant="text" color="error" onClick={handleOpen}>
                        {t('configure')}
                    </Button>
                </Grid>
            }
            <Dialog fullWidth={true} maxWidth="lg" open={open}
                onClose={(event, reason) => { if (reason !== 'backdropClick') { handleClose(); } }}
            >
                <DialogTitle variant="h3">{t("configureDesc")}</DialogTitle>
                <DialogContent>
                    <Box mb={3}>
                        <FormControlLabel
                            control={
                                <Switch
                                    color="error"
                                    checked={toolbarOptions.showLabel}
                                    onChange={handleOptionShowLabelChange}
                                    name="showLabel"
                                />
                            }
                            label={t('showLabel')}
                        />
                        <Divider sx={{ my: 2 }} />
                        <Typography variant="h3" gutterBottom>{t("enabledNavs")}</Typography>
                        <Paper variant="outlined" style={{ padding: '16px', marginBottom: '16px' }}>
                            <DndContext
                                onDragStart={handleDragStart}
                                onDragEnd={handleDragEnd}
                                sensors={sensors}
                                collisionDetection={pointerWithin}
                            >
                                <Box display="flex" justifyContent="space-between">
                                    <Box flex={1} mr={2} ref={leftAreaRef}>
                                        <Typography variant="h6" gutterBottom>{t('left')}</Typography>
                                        <DroppableArea id="left">
                                            <Box display="flex" flexWrap="wrap" gap={1}>
                                                {toolbarOptions.navs.filter(option => option.enable && option.align === 'flex-start').sort((a, b) => a.sort - b.sort).map((option) => (
                                                    <DraggableItem key={option.id} id={option.id} name={option.name} showLabel={option.showLabel} />
                                                ))}
                                            </Box>
                                        </DroppableArea>
                                    </Box>
                                    <Box flex={1} ref={rightAreaRef}>
                                        <Typography variant="h6" gutterBottom>{t('right')}</Typography>
                                        <DroppableArea id="right">
                                            <Box display="flex" flexWrap="wrap" gap={1}>
                                                {toolbarOptions.navs.filter(option => option.enable && option.align === 'flex-end').sort((a, b) => a.sort - b.sort).map((option) => (
                                                    <DraggableItem key={option.id} id={option.id} name={option.name} showLabel={option.showLabel} />
                                                ))}
                                            </Box>
                                        </DroppableArea>
                                    </Box>
                                </Box>
                                <DragOverlay>
                                    {activeId ? (
                                        <DraggableItem id={activeId} name={activeName} showLabel={activeShowLabel} />
                                    ) : null}
                                </DragOverlay>
                            </DndContext>
                        </Paper>
                    </Box>
                    <Box mb={3}>
                        <Typography variant="h3" gutterBottom>{t("disabledNavs")}</Typography>
                        <Paper variant="outlined" style={{ padding: '16px' }}>
                            <Box display="grid" gridTemplateColumns="repeat(auto-fill, minmax(200px, 1fr))" gap={1}>
                                {toolbarOptions.navs.filter(option => !option.enable).sort((a, b) => a.sort - b.sort).map((option) => (
                                    <Button key={option.id} endIcon={<Add />} variant="outlined" size="small" onClick={() => handleEnable(option.id)}>
                                        {t(option.name)}
                                    </Button>
                                ))}
                            </Box>
                        </Paper>
                    </Box>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleClose} color="error">
                        {t("close")}
                    </Button>
                </DialogActions>
            </Dialog>
        </Grid>
    );
}
