import { recordDebugLog } from '../../../utils/helpers';
import { sendRuntimeMessage } from '../../browers/runtime';
import quickAccessStore, { localCacheQuickAccessInstance, restoreQuickAccess } from '../../stores/quickAccessStore';

/**
 * Retrieves quick access data from local cache
 * @returns {Promise<Object|null>} Quick access data or null if error
 */
export async function getQuickAccessData() {
    try {
        const quickAccessInstance = await localCacheQuickAccessInstance();
        if (!quickAccessInstance) {
            recordDebugLog('[syncService] [quickAccess] Failed to get quick access instance');
            return null;
        }
        return await quickAccessInstance.get("quickAccess");
    } catch (error) {
        recordDebugLog(`[syncService] [quickAccess] Failed to get quick access data: ${error.message}`);
        return null;
    }
}

/**
 * Applies quick access data from cache
 * @param {string} dataKey - Key to retrieve data from cache
 * @param {Object} localCache - Local cache instance
 * @returns {Promise<void>}
 */
export async function applyQuickAccess(dataKey, localCache) {
    if (!dataKey || !localCache) {
        recordDebugLog(`[syncService] [${dataKey}] Invalid parameters for applying quick access`, dataKey);
        return;
    }

    try {
        const cachedData = await localCache.get(dataKey);

        if (!cachedData?.items?.length) {
            recordDebugLog(`[syncService] [${dataKey}] No valid quick access data to apply`, dataKey);
            return;
        }

        await quickAccessStore.getState().restoreQuickAccess(cachedData.items);
        await sendRuntimeMessage("refresh_quick_access");
        recordDebugLog(`[syncService] [${dataKey}] Successfully applied quick access data`, dataKey);
    } catch (error) {
        recordDebugLog(`[syncService] [${dataKey}] Failed to apply quick access: ${error.message}`, dataKey);
        throw error;
    }
}