import { Close } from "@mui/icons-material";
import { IconButton, ListItemButton, Stack, Typography, Box } from "@mui/material";
import React from "react";
import snapshotStore from "../../../../core/stores/snapshotStore";
import { formatDateYmdHis } from "../../../../utils/helpers";
import { toast } from "react-toastify";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import { CloudDoneOutlined } from "@mui/icons-material";
import { FlashAuto } from "@mui/icons-material";

export default function SnapshotItem({ summary }) {
    const { t } = useTranslationContext('options', { keyPrefix: 'snapshots' });
    const selectdSnapshotId = snapshotStore(state => state.selectdSnapshotId);

    const handleClick = async (event) => {
        event.stopPropagation();
        snapshotStore.setState({
            selectdSnapshotId: summary.id,
            selectedTabs: {},
            selectedGroups: {}
        });
    }

    const handleDelete = async (event) => {
        event.stopPropagation();
        try {
            await snapshotStore.getState().removeSnapshot(summary.id);
            toast.success(t('snapshotDeletedSuccess'));
        } catch (error) {
            toast.error(t('snapshotDeletedFailed'));
        }
    }

    const isSelected = summary.id === selectdSnapshotId;

    return (
        <ListItemButton
            onClick={handleClick}
            selected={isSelected}
            sx={{
                borderRadius: '12px',
                transition: 'all 0.2s ease',
                marginBottom: 1,
                border: '1px solid',
                borderColor: isSelected ? '#1976d2' : '#e0e0e0',
                '&:hover': {
                    borderColor: isSelected ? '#1976d2' : '#bdbdbd',
                    backgroundColor: '#f5f5f5',
                },
                '&.Mui-selected': {
                    backgroundColor: isSelected ? 'rgba(25, 118, 210, 0.1)' : 'transparent',
                    '&:hover': {
                        backgroundColor: 'rgba(25, 118, 210, 0.2)',
                    }
                }
            }}
        >
            <Stack direction="row" width="100%" alignItems="center" spacing={2}>
                <Box flex={1}>
                    <Typography
                        variant="subtitle1"
                        sx={{
                            fontWeight: isSelected ? 600 : 500,
                            color: '#000',
                            marginBottom: 0.5
                        }}
                    >
                        {formatDateYmdHis(summary.createdAt)}
                    </Typography>
                    <Typography
                        variant="body2"
                        sx={{
                            color: '#666',
                            marginBottom: summary.deviceName ? 1 : 0
                        }}
                    >
                        {t('windowCount', { count: summary.windowCount })} • {t('tabCount', { count: summary.tabCount })}
                    </Typography>
                    {summary.deviceName && (
                        <Stack
                            direction="row"
                            spacing={1}
                            alignItems="center"
                            sx={{
                                backgroundColor: 'rgba(25, 118, 210, 0.08)',
                                borderRadius: '4px',
                                padding: '4px 8px',
                                display: 'inline-flex',
                                width: 'fit-content',
                                border: '1px solid rgba(25, 118, 210, 0.2)'
                            }}
                        >
                            {summary.isAutoCreated ? <FlashAuto sx={{
                                fontSize: 14,
                                color: '#1976d2'
                            }} /> : <CloudDoneOutlined
                                sx={{
                                    fontSize: 14,
                                    color: '#1976d2'
                                }}
                            />}
                            <Typography
                                variant="caption"
                                sx={{
                                    color: '#1976d2',
                                    fontWeight: 500,
                                    letterSpacing: '0.01em'
                                }}
                            >
                                {summary.deviceName}
                            </Typography>
                        </Stack>
                    )}
                </Box>
                <IconButton
                    onClick={handleDelete}
                    size="small"
                    sx={{
                        opacity: 0,
                        transition: 'all 0.2s ease',
                        '.MuiListItemButton-root:hover &': {
                            opacity: 1,
                            transform: 'scale(1)'
                        },
                        transform: 'scale(0.8)',
                        color: '#666',
                        '&:hover': {
                            color: '#d32f2f',
                            backgroundColor: 'rgba(211, 47, 47, 0.08)'
                        }
                    }}
                >
                    <Close fontSize="small" />
                </IconButton>
            </Stack>
        </ListItemButton>
    )
}