import React, { useState } from 'react';
import {
    Dialog,
    DialogActions,
    DialogContent,
    DialogTitle,
    Typography,
    TextField,
    Grid,
    Stack,
    Button
} from '@mui/material';
import { useTranslationContext } from '../../../../Providers/TranslationProvider';
import { setLocalPassword } from '../../../../../core/user';
import { sendRuntimeMessage } from '../../../../../core/browers/runtime';

const ChangeLocalPassword = () => {
    const { t } = useTranslationContext('options', { keyPrefix: 'settings.syncToCloud' });

    const [localPassword, setLocalPasswordState] = useState('');
    const [passwordError, setPasswordError] = useState('');
    const [isSaving, setIsSaving] = useState(false);
    const [dialogOpen, setDialogOpen] = useState(false);

    const handlePasswordChange = (event) => {
        setLocalPasswordState(event.target.value);
        setPasswordError('');
    };

    const handlePasswordSave = async () => {
        // const passwordRegex = /^(?=.*[A-Za-z])(?=.*\d)[A-Za-z\d]{6,}$/;
        // if (!passwordRegex.test(localPassword)) {
        //     setPasswordError(t('passwordError'));
        //     return;
        // }
        setIsSaving(true);
        try {
            await setLocalPassword(localPassword);
            await sendRuntimeMessage('reset_sync_service');
            setDialogOpen(false);
        } finally {
            setIsSaving(false);
        }
    };

    const handleDialogOpen = () => {
        setDialogOpen(true);
    };

    const handleDialogClose = () => {
        setDialogOpen(false);
    };

    return (
        <Grid container alignItems="flex-start">
            <Grid item xs={6}>
                <Typography variant="h3" mb={1}>{t('changeLocalPassword')}</Typography>
                <Typography variant="body1" color="text.secondary">
                    {t('changeLocalPasswordDesc')}
                </Typography>
            </Grid>
            <Grid item xs={6} sx={{ display: "flex", alignItems: "center", alignSelf: "center" }}>
                <Button variant='outlined' onClick={handleDialogOpen}>{t('changeLocalPassword')}</Button>
            </Grid>
            <Dialog open={dialogOpen} onClose={(event, reason) => { if (reason !== 'backdropClick') { handleDialogClose } }}>
                <DialogTitle variant='h3'>{t('changeLocalPassword')}</DialogTitle>

                <DialogContent>
                    <Typography variant='body1' color='error'>
                        {t('changeLocalPasswordDesc')}
                    </Typography>
                    <TextField
                        size='small'
                        label={t('setLocalPasswordTitle')}
                        type="password"
                        value={localPassword}
                        onChange={handlePasswordChange}
                        margin="normal"
                        error={!!passwordError}
                        helperText={passwordError}
                        fullWidth
                    />
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleDialogClose} color="primary">
                        {t('cancel')}
                    </Button>
                    <Button variant='contained' onClick={handlePasswordSave} color="error" disabled={isSaving}>
                        {t('save')}
                    </Button>
                </DialogActions>
            </Dialog>
        </Grid>
    );
};

export default ChangeLocalPassword;
