import { orderBy } from 'lodash-es';
import { sha256 } from '../../../utils/crypto';
import { recordDebugLog } from '../../../utils/helpers';
import { getLocalPassword } from '../../user';

export async function calculateDataHash(dataKey, items) {
    recordDebugLog(`[syncService][${dataKey}] Calculating data hash...`);

    // Early validation of items
    if (!items) {
        recordDebugLog(`[syncService][${dataKey}] No items provided, returning hash of empty data`);
        const localPassword = (await getLocalPassword());
        return await sha256(localPassword + (Array.isArray(items) ? '[]' : '{}'));
    }

    let hash;
    let localPassword;
    try {
        switch (dataKey) {
            case 'windowTabs':
                hash = await calculateWindowTabsHash(items);
                break;
            case 'settings':
                hash = await calculateSettingsHash(items);
                break;
            case 'siteConfigs':
                hash = await calculateSiteConfigsHash(items);
                break;
            case 'quickAccess':
                hash = await calculateQuickAccessHash(items);
                break;
            case 'recentClosedTabs':
                hash = await calculateRecentClosedTabsHash(items);
                break;
            default:
                localPassword = (await getLocalPassword());
                hash = await sha256(localPassword + JSON.stringify(items));
        }
        recordDebugLog(`[syncService][${dataKey}] Calculated hash: ${hash}`);
        return hash;
    } catch (error) {
        recordDebugLog(`[syncService][${dataKey}] Error calculating hash: ${error.message}`);
        throw error;
    }
}

async function calculateWindowTabsHash(items) {
    if (!Array.isArray(items)) {
        recordDebugLog('[syncService][windowTabs] Invalid items format, returning empty array hash');
        const localPassword = (await getLocalPassword());
        return await sha256(localPassword + '[]');
    }

    const simplifiedWindows = items.map(window => ({
        id: window.id,
        tabs: orderBy(
            window.tabs?.map(tab => ({
                url: tab.url,
                title: tab.title,
                pinned: tab.pinned,
                index: tab.index,
                groupId: tab.groupId
            })) || [],
            ['url'],
            ['asc']
        ),
        groups: window.groups ? orderBy(
            window.groups.map(group => ({
                title: group.title,
                color: group.color
            })),
            ['title'],
            ['asc']
        ) : []
    }));

    recordDebugLog(`[syncService][windowTabs] Simplified ${items.length} windows for hashing`);
    const localPassword = (await getLocalPassword());
    return await sha256(localPassword + JSON.stringify(simplifiedWindows));
}

async function calculateSettingsHash(items) {
    if (!items || typeof items !== 'object' || Array.isArray(items)) {
        recordDebugLog('[syncService][settings] Invalid items format, returning empty object hash');
        const localPassword = (await getLocalPassword());
        return await sha256(localPassword + '{}');
    }

    const sorted = Object.keys(items)
        .sort()
        .reduce((acc, key) => {
            acc[key] = items[key];
            return acc;
        }, {});

    recordDebugLog(`[syncService][settings] Sorted ${Object.keys(items).length} settings keys for hashing`);
    const localPassword = (await getLocalPassword());
    return await sha256(localPassword + JSON.stringify(sorted));
}

async function calculateSiteConfigsHash(items) {
    if (!Array.isArray(items)) {
        recordDebugLog('[syncService][siteConfigs] Invalid items format, returning empty array hash');
        const localPassword = (await getLocalPassword());
        return await sha256(localPassword + '[]');
    }

    const sortedConfigs = orderBy(items, ['hostname'], ['asc']);

    recordDebugLog(`[syncService][siteConfigs] Sorted ${items.length} site configs for hashing`);
    const localPassword = (await getLocalPassword());
    return await sha256(localPassword + JSON.stringify(sortedConfigs));
}

async function calculateQuickAccessHash(items) {
    if (!Array.isArray(items)) {
        recordDebugLog('[syncService][quickAccess] Invalid items format, returning empty array hash');
        const localPassword = (await getLocalPassword());
        return await sha256(localPassword + '[]');
    }

    const simplifiedItems = items.map(item => ({
        uuid: item.uuid,
        url: item.url,
        title: item.title,
        favIconUrl: item.favIconUrl,
        sortIndex: item.sortIndex,
        urlsCount: item.urls?.length || 0
    }));

    const sortedItems = orderBy(simplifiedItems, ['uuid'], ['asc']);
    recordDebugLog(`[syncService][quickAccess] Simplified and sorted ${items.length} quick access items for hashing`);
    const localPassword = (await getLocalPassword());
    return await sha256(localPassword + JSON.stringify(sortedItems));
}

async function calculateRecentClosedTabsHash(items) {
    if (!Array.isArray(items)) {
        recordDebugLog('[syncService][recentClosedTabs] Invalid items format, returning empty array hash');
        const localPassword = (await getLocalPassword());
        return await sha256(localPassword + '[]');
    }

    const simplifiedItems = orderBy(
        items.map(item => ({ url: item.url })),
        ['url'],
        ['asc']
    );
    recordDebugLog(`[syncService][recentClosedTabs] Simplified and sorted ${items.length} recently closed tabs for hashing`);
    const localPassword = (await getLocalPassword());
    return await sha256(localPassword + JSON.stringify(simplifiedItems));
}