import { Box, Checkbox, ListItem, ListItemButton, Stack, Typography } from "@mui/material";
import React from "react";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import LinkAvatar from "../../../component/links/LinkAvatar";
import { decodedUrl, faviconURL } from "../../../../utils/helpers";
import snapshotStore from "../../../../core/stores/snapshotStore";
import { shallow } from "zustand/shallow";

const WindowTabItem = React.memo(({ item }) => {
    const { t } = useTranslationContext('options', { keyPrefix: 'snapshots' });
    const { selectedTabs } = snapshotStore(
        (state) => ({
            selectedTabs: state.selectedTabs,
        }),
        shallow
    );
    const selected = selectedTabs[item.windowId]?.includes(item.id) || false;

    const handleOpenLink = () => {
        chrome.tabs.create({ url: item.url, active: false });
    };

    const handleCheckboxChange = React.useCallback((event) => {
        const check = event.target.checked;

        snapshotStore.setState(state => {
            if (!state.selectedTabs[item.windowId]) {
                state.selectedTabs[item.windowId] = [];
            }

            if (check) {
                if (!state.selectedTabs[item.windowId].includes(item.id)) {
                    state.selectedTabs[item.windowId].push(item.id);
                }
            } else {
                state.selectedTabs[item.windowId] = state.selectedTabs[item.windowId].filter(
                    id => id !== item.id
                );
            }
        });
    }, [item.id, item.windowId]);

    const handleCheckboxClick = (event) => {
        event.stopPropagation();
    };

    return (
        <ListItem disablePadding sx={{ minHeight: '36px' }}>
            <ListItemButton
                selected={selected}
                component="div"
                disableGutters
                onClick={handleOpenLink}
                sx={{
                    py: 0.25,
                    minHeight: '36px',
                    '&:hover': {
                        backgroundColor: 'action.hover',
                    }
                }}
            >
                <Stack
                    direction="row"
                    sx={{
                        width: "100%",
                        paddingX: "4px",
                    }}
                    alignItems="center"
                    spacing={0.75}
                >
                    <LinkAvatar
                        avatarUrl={item.favIconUrl || faviconURL(item.url)}
                        sx={{
                            width: 16,
                            height: 16,
                            borderRadius: '2px'
                        }}
                    />
                    <Box sx={{ minWidth: 0, flex: 1 }}>
                        <Typography
                            variant="body2"
                            noWrap
                            sx={{
                                lineHeight: 1.1,
                                fontSize: '0.8125rem',
                                fontWeight: 500
                            }}
                        >
                            {item.title}
                        </Typography>
                        <Typography
                            variant="caption"
                            color="text.secondary"
                            sx={{
                                display: 'block',
                                lineHeight: 1.1,
                                fontSize: '0.75rem',
                                opacity: 0.7
                            }}
                            noWrap
                        >
                            {decodedUrl(item.url)}
                        </Typography>
                    </Box>
                    <Checkbox
                        size="small"
                        checked={selected}
                        onChange={handleCheckboxChange}
                        onClick={handleCheckboxClick}
                        sx={{
                            p: 0.25,
                            '& .MuiSvgIcon-root': {
                                fontSize: 18
                            }
                        }}
                    />
                </Stack>
            </ListItemButton>
        </ListItem>
    );
}, (prevProps, nextProps) => {
    return (
        prevProps.item.id === nextProps.item.id &&
        prevProps.item.windowId === nextProps.item.windowId &&
        prevProps.item.title === nextProps.item.title &&
        prevProps.item.url === nextProps.item.url
    );
});

export default WindowTabItem;
