import { Box, Button, Divider, Stack, Typography } from "@mui/material";
import React, { useEffect } from "react";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import snapshotStore from "../../../../core/stores/snapshotStore";
import SnapshotItem from "./SnapshotItem";
import { toast } from "react-toastify";
import { OverlayScrollbarsComponent } from "overlayscrollbars-react";
import AddIcon from '@mui/icons-material/Add';
import UploadIcon from '@mui/icons-material/Upload';


export default function SideList() {
    const { t } = useTranslationContext('options', { keyPrefix: 'snapshots' });

    const { fetchSummaries } = snapshotStore((state) => ({
        fetchSummaries: state.fetchSummaries
    }))
    // Get sorted summaries and remove extras
    const allSummaries = [...snapshotStore(state => state.summaries)]
        .sort((a, b) => b.createdAt - a.createdAt);
    const summaries = allSummaries.slice(0, 50);
    const snapshotsToRemove = allSummaries.slice(50);

    useEffect(() => {
        fetchSummaries();
    }, [])

    // Cleanup extra snapshots
    useEffect(() => {
        snapshotsToRemove.forEach(snapshot => {
            snapshotStore.getState().removeSnapshot(snapshot.id);
        });
    }, [snapshotsToRemove]);

    // Select first snapshot if none selected
    useEffect(() => {
        const selectdSnapshotId = snapshotStore.getState().selectdSnapshotId;
        if (!selectdSnapshotId && summaries.length > 0) {
            snapshotStore.setState({ selectdSnapshotId: summaries[0].id });
        }
    }, [summaries]);

    const handleCreateSnapshot = async () => {
        try {
            await snapshotStore.getState().addSnapshot();

            // Get latest snapshot and select it
            const latestSnapshot = [...snapshotStore.getState().summaries]
                .sort((a, b) => b.createdAt - a.createdAt)[0];
            snapshotStore.setState({
                selectdSnapshotId: latestSnapshot.id,
                selectedTabs: []
            });

            // Cleanup old snapshots
            const updatedSummaries = [...snapshotStore.getState().summaries]
                .sort((a, b) => b.createdAt - a.createdAt);
            const latestFiftySummaries = updatedSummaries.slice(0, 50);
            const threeMonthsAgo = Date.now() - (3 * 30 * 24 * 60 * 60 * 1000);

            const snapshotsToRemove = updatedSummaries.filter(snapshot =>
                !latestFiftySummaries.includes(snapshot) ||
                snapshot.createdAt < threeMonthsAgo
            );

            for (const snapshot of snapshotsToRemove) {
                await snapshotStore.getState().removeSnapshot(snapshot.id);
            }

            snapshotStore.setState({
                summaries: latestFiftySummaries.filter(
                    snapshot => snapshot.createdAt >= threeMonthsAgo
                )
            });

            toast.success(t('snapshotCreatedSuccess'));
        } catch (error) {
            toast.error(t('snapshotCreatedFailed'));
        }
    };

    const handleImportSnapshot = async (event) => {
        const file = event.target.files[0];
        if (!file) return;

        const reader = new FileReader();
        reader.onload = async (e) => {
            try {
                const importedData = JSON.parse(e.target.result);
                const store = snapshotStore.getState();

                if (Array.isArray(importedData.snapshots)) {
                    let successCount = 0;
                    let failureCount = 0;

                    for (const snapshot of importedData.snapshots) {
                        const exists = store.summaries.find(s => s.id === snapshot.id);
                        if (exists) {
                            failureCount++;
                            continue;
                        }

                        try {
                            await store.addImportedSnapshot(snapshot);
                            successCount++;
                        } catch {
                            failureCount++;
                        }
                    }

                    if (successCount > 0) {
                        toast.success(t('snapshotImportedSuccess', { count: successCount, error: "" }));
                    }
                    if (failureCount > 0) {
                        toast.error(t('snapshotImportFailed', { count: failureCount, error: "" }));
                    }
                } else {
                    const exists = store.summaries.find(s => s.id === importedData.id);
                    if (exists) {
                        toast.error(t('snapshotImportFailedDuplicate'));
                        return;
                    }

                    await store.addImportedSnapshot(importedData);
                    toast.success(t('snapshotImportedSuccess', { count: 1 }));
                }
            } catch (error) {
                console.error("Error importing snapshot:", error);
                toast.error(t('snapshotImportFailed', { count: 0, error: error.message }));
            }
        };
        reader.readAsText(file);
    };

    return (
        <Box sx={{
            backgroundColor: 'background.paper',
            borderRadius: 2,
            p: 2,
            height: '100%',
            boxShadow: 1
        }}>
            <Stack spacing={2} mb={3}>
                <Button
                    fullWidth
                    size="large"
                    variant="contained"
                    color="primary"
                    onClick={handleCreateSnapshot}
                    startIcon={<AddIcon />}
                >
                    {t('createSnapshot')}
                </Button>
                <Button
                    fullWidth
                    size="large"
                    variant="outlined"
                    component="label"
                    startIcon={<UploadIcon />}
                >
                    {t('importSnapshot')}
                    <input
                        type="file"
                        accept=".json"
                        hidden
                        onChange={handleImportSnapshot}
                    />
                </Button>
            </Stack>

            <Typography variant="h6" sx={{
                mb: 2,
                color: 'text.primary',
                fontWeight: 500
            }}>
                {t('title')} ({summaries.length})
            </Typography>

            <OverlayScrollbarsComponent defer style={{ maxHeight: 'calc(100vh - 300px)' }}>
                <Stack spacing={1}>
                    {summaries.map(summary => (
                        <SnapshotItem key={summary.id} summary={summary} />
                    ))}
                </Stack>
            </OverlayScrollbarsComponent>
        </Box>
    );
}