import React, { useEffect, useState } from 'react';
import {
    FormControl,
    RadioGroup,
    FormControlLabel,
    Radio,
    Typography,
    Box,
    Grid,
    Stack
} from '@mui/material';
import { useTranslationContext } from '../../../../Providers/TranslationProvider';
import { SYNC } from '../../../../../configs/app';
import { setUserConfig } from '../../../../../core/user';
import { sendRuntimeMessage } from '../../../../../core/browers/runtime';

const SyncModeSection = ({ syncMode, setSyncMode }) => {
    const { t } = useTranslationContext('options', { keyPrefix: 'settings.syncToCloud.mode' });


    const handleModeChange = async (event) => {
        const newSyncMode = event.target.value;

        try {
            await setUserConfig('syncMode', newSyncMode);
            setSyncMode(newSyncMode);
            sendRuntimeMessage("sync_mode_changed", { syncMode: newSyncMode })
        } catch (error) {
            console.error('Failed to update sync mode:', error);
        }
    };

    return (
        <Grid container alignItems="flex-start">
            <Grid item xs={6}>
                <Typography variant="h3" mb={1}>{t('title')}</Typography>
                <Typography variant="body1" color="text.secondary">
                    {t('description')}
                </Typography>
            </Grid>
            <Grid item xs={6}>
                <FormControl component="fieldset">
                    <RadioGroup
                        row
                        value={syncMode}
                        onChange={handleModeChange}
                    >
                        {Object.values(SYNC.MODES).map((mode) => (
                            <FormControlLabel
                                key={mode}
                                value={mode}
                                color='error'
                                control={<Radio />}
                                label={t(`modes.${mode}`)}
                            />
                        ))}
                    </RadioGroup>
                </FormControl>
            </Grid>
        </Grid>
    );
};

export default SyncModeSection;
