import React from 'react';
import { Box, Card, CardContent, FormControlLabel, Switch, Typography, Grid, Stack, IconButton, Menu, MenuItem, Button, Dialog, DialogTitle, DialogContent, RadioGroup, Radio, FormControl, FormControlLabel as RadioLabel, DialogActions, Tooltip, TextField, Divider } from '@mui/material';
import { useTranslationContext } from '../../../../Providers/TranslationProvider';
import userStore from '../../../../../core/stores/userStore';
import { SYNC } from '../../../../../configs/app';
import SyncIcon from '@mui/icons-material/Sync';
import CheckCircleIcon from '@mui/icons-material/CheckCircle';
import MoreVertIcon from '@mui/icons-material/MoreVert';
import { sendRuntimeMessage } from '../../../../../core/browers/runtime';
import { toast } from 'react-toastify';

const SyncDataOptionsSection = ({ syncMode }) => {

    const { t } = useTranslationContext('options', { keyPrefix: 'settings.syncToCloud.dataOptions' });
    const { updateSetting, syncConfig, isUserLoggedIn } = userStore((state) => ({
        updateSetting: state.updateSetting,
        syncConfig: state.settings.syncConfig,
        isUserLoggedIn: !!state.userInfo?.id
    }));

    const handleSwitchChange = (key) => async (event) => {

        const newSyncConfig = {
            ...syncConfig,
            syncDataOptions: {
                ...syncConfig.syncDataOptions,
                [key]: { ...syncConfig.syncDataOptions[key], enabled: event.target.checked }
            }
        };
        await updateSetting('syncConfig', newSyncConfig);
        await sendRuntimeMessage("update_setting", {
            key: "syncConfig",
            value: newSyncConfig
        });
    };

    const isDisabled = syncMode === SYNC.MODES.DISABLED || !isUserLoggedIn;

    const [anchorEl, setAnchorEl] = React.useState(null);
    const [selectedKey, setSelectedKey] = React.useState(null);
    const [tempApplyMode, setTempApplyMode] = React.useState('');
    const [tempSkipLastWindow, setTempSkipLastWindow] = React.useState(false);
    const [tempDebounceMs, setTempDebounceMs] = React.useState('30');
    const [syncingStates, setSyncingStates] = React.useState({});
    const [syncSuccessStates, setSyncSuccessStates] = React.useState({});
    const [openDialog, setOpenDialog] = React.useState(false);

    const handleSyncClick = (key) => async () => {
        setSyncingStates(prev => ({ ...prev, [key]: true }));
        setSyncSuccessStates(prev => ({ ...prev, [key]: false }));

        try {
            const response = await sendRuntimeMessage('sync_now', { data_type: key });
            if (!response.success && response.error) {
                toast.error(t(response.error, { ns: "error", keyPrefix: "" }));
            } else {
                setSyncSuccessStates(prev => ({ ...prev, [key]: true }));
            }
        } finally {
            setSyncingStates(prev => ({ ...prev, [key]: false }));
        }
    };

    const handleMoreOptionsClick = () => {
        setTempApplyMode(syncConfig.syncDataOptions.windowTabs.applyMode);
        setTempSkipLastWindow(syncConfig.syncDataOptions.windowTabs.skipLastWindow);
        setTempDebounceMs(String(syncConfig.syncDataOptions.windowTabs.debounceMs / 1000)); // Convert ms to seconds
        setOpenDialog(true);
    };

    const handleApplyModeSelect = (event) => {
        setTempApplyMode(event.target.value);
    };

    const handleSkipLastWindowChange = (event) => {
        setTempSkipLastWindow(event.target.checked);
    };

    const handleDebounceChange = (event) => {
        setTempDebounceMs(event.target.value);
    };

    const handleSave = async () => {
        const debounceValue = Number(tempDebounceMs);
        if (debounceValue && debounceValue < 30) {
            toast.error(t('Sync interval cannot be less than 30 seconds', { ns: "error", keyPrefix: "" }));
            return;
        }

        const newSyncConfig = {
            ...syncConfig,
            syncDataOptions: {
                ...syncConfig.syncDataOptions,
                windowTabs: {
                    ...syncConfig.syncDataOptions.windowTabs,
                    applyMode: tempApplyMode,
                    skipLastWindow: tempSkipLastWindow,
                    debounceMs: (debounceValue || 30) * 1000 // Convert seconds to ms, default to 30 if empty
                }
            }
        };
        await updateSetting('syncConfig', newSyncConfig);
        await sendRuntimeMessage("update_setting", {
            key: "syncConfig",
            value: newSyncConfig
        });


        setOpenDialog(false);
    };

    const handleClose = () => {
        setOpenDialog(false);
    };

    return (
        <Grid container alignItems="flex-start">
            <Grid item xs={6}>
                <Typography variant="h3" mb={1}>{t('title')}</Typography>
                <Typography variant="body1" color="text.secondary">
                    {t('description')}
                </Typography>
            </Grid>
            <Grid item xs={6}>
                <Stack spacing={1}>
                    {Object.keys(syncConfig.syncDataOptions).map((key) => (
                        <Box key={key} sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                            <FormControlLabel
                                control={
                                    <Switch
                                        color='error'
                                        checked={syncConfig.syncDataOptions[key].enabled}
                                        onChange={handleSwitchChange(key)}
                                        disabled={isDisabled}
                                    />
                                }
                                label={t(`${key}.title`)}
                            />
                            {syncConfig.syncDataOptions[key].enabled && (
                                <>
                                    <Tooltip title={t('syncNow', { keyPrefix: 'settings.syncToCloud' })}>
                                        <IconButton
                                            size="small"
                                            onClick={handleSyncClick(key)}
                                            disabled={isDisabled || syncingStates[key]}
                                        >
                                            {syncSuccessStates[key] ? (
                                                <CheckCircleIcon fontSize="small" color="success" />
                                            ) : (
                                                <SyncIcon
                                                    fontSize="small"
                                                    sx={{
                                                        animation: syncingStates[key] ? 'spin 1s linear infinite' : 'none',
                                                        '@keyframes spin': {
                                                            '0%': { transform: 'rotate(0deg)' },
                                                            '100%': { transform: 'rotate(360deg)' }
                                                        }
                                                    }}
                                                />
                                            )}
                                        </IconButton>
                                    </Tooltip>
                                    {key === 'windowTabs' && (
                                        <Button
                                            sx={{ ml: 1 }}
                                            size="small"
                                            onClick={handleMoreOptionsClick}
                                            disabled={isDisabled}
                                            variant="outlined"
                                            endIcon={<MoreVertIcon />}
                                        >
                                            {t('windowTabs.moreOptions')}
                                        </Button>
                                    )}
                                </>
                            )}
                        </Box>
                    ))}
                </Stack>

                <Dialog
                    open={openDialog}
                    onClose={(event, reason) => { if (reason !== 'backdropClick') { handleClose } }}
                    maxWidth="xs"
                    fullWidth
                >
                    <DialogTitle variant='h3'>{t('windowTabs.optionsTitle')}</DialogTitle>
                    <DialogContent>
                        <Box sx={{ mb: 3 }}>
                            <Typography variant="h4" sx={{ mb: 1 }}>{t('windowTabs.syncAfterActionTitle')}</Typography>
                            <FormControl>
                                <RadioGroup
                                    value={tempApplyMode}
                                    onChange={handleApplyModeSelect}
                                >
                                    {['append', 'new', 'replace', 'createSnapshot'].map((mode) => (
                                        <RadioLabel
                                            sx={{ my: 1 }}
                                            key={mode}
                                            value={mode}
                                            control={<Radio />}
                                            label={
                                                <Box>
                                                    <Typography variant="body1">
                                                        {t(`windowTabs.applyModes.${mode}.title`)}
                                                    </Typography>
                                                    <Typography variant="body2" color="text.secondary">
                                                        {t(`windowTabs.applyModes.${mode}.description`)}
                                                    </Typography>
                                                </Box>
                                            }
                                        />
                                    ))}
                                </RadioGroup>
                            </FormControl>
                        </Box>

                        <Divider sx={{ my: 2 }} />

                        <Box sx={{ mb: 3 }}>
                            <FormControlLabel
                                control={
                                    <Switch
                                        checked={tempSkipLastWindow}
                                        onChange={handleSkipLastWindowChange}
                                    />
                                }
                                label={t('windowTabs.skipLastWindow')}
                            />
                            <Typography variant="body2" color="text.secondary" sx={{ mt: 1, ml: 4 }}>
                                {t('windowTabs.skipLastWindowDescription')}
                            </Typography>
                        </Box>

                        <Divider sx={{ my: 2 }} />

                        <Box>
                            <TextField
                                size="small"
                                label={t('windowTabs.debounceMs')}
                                value={tempDebounceMs}
                                onChange={handleDebounceChange}
                                InputProps={{
                                    endAdornment: <Typography>s</Typography>
                                }}
                            />
                            <Typography variant="body2" color="text.secondary" sx={{ mt: 1 }}>
                                {t('windowTabs.debounceMsDescription')}
                            </Typography>
                        </Box>
                    </DialogContent>
                    <DialogActions>
                        <Button onClick={handleClose}>{t('windowTabs.close')}</Button>
                        <Button onClick={handleSave} variant="contained" color="error">
                            {t('windowTabs.save')}
                        </Button>
                    </DialogActions>
                </Dialog>
            </Grid>
        </Grid>
    );
};

export default SyncDataOptionsSection;
