import React, { useState } from "react";
import { userStore } from "../../../../core/stores/userStore";
import { useTranslationContext } from "../../../Providers/TranslationProvider";

import { Grid, Typography, FormControlLabel, Switch, Button, Dialog, DialogTitle, DialogContent, DialogActions, FormGroup, FormControl, FormLabel, Checkbox, Divider } from "@mui/material";
import { sendRuntimeMessage } from "../../../../core/browers/runtime";
import { ArrowRight } from "@mui/icons-material";

export default function ClearTabsBtn() {

    const { t } = useTranslationContext("options", { keyPrefix: "settings.appearance.clearTabsBtn" });

    const { updateSetting, clearTabsBtn } = userStore((state) => ({
        updateSetting: state.updateSetting,
        clearTabsBtn: state.settings.clearTabsBtn,
    }));

    const [open, setOpen] = useState(false);
    const [options, setOptions] = useState([
        { label: t("options.createSnapshot"), key: "createSnapshot", value: clearTabsBtn.options.createSnapshot },
        { label: t("options.closeInactiveTabs"), key: "closeInactiveTabs", value: clearTabsBtn.options.closeInactiveTabs },
        { label: t("options.closeDiscardTabs"), key: "closeDiscardTabs", value: clearTabsBtn.options.closeDiscardTabs },
        { label: t("options.skipSoundTabs"), key: "skipSoundTabs", value: clearTabsBtn.options.skipSoundTabs },
        { label: t("options.skipCurrentTab"), key: "skipCurrentTab", value: clearTabsBtn.options.skipCurrentTab },
        { label: t("options.confirm"), key: "confirm", value: clearTabsBtn.options.confirm },
    ]);

    const handleEnableChange = async (event) => {
        const newValue = event.target.checked;
        await updateSetting('clearTabsBtn', {
            ...clearTabsBtn,
            enable: newValue
        });
        await sendRuntimeMessage("update_setting", {
            key: "clearTabsBtn",
            value: {
                ...clearTabsBtn,
                enable: newValue
            }
        });
    };

    const handleMoreOptionsClick = () => {
        setOpen(true);
    };

    const handleDialogClose = () => {
        setOpen(false);
    };

    const handleOptionChange = async (event) => {
        const newOptions = options.map(option =>
            option.key === event.target.name ? { ...option, value: event.target.checked } : option
        );
        setOptions(newOptions);

        const updatedOptions = {
            ...clearTabsBtn.options,
            [event.target.name]: event.target.checked
        };

        await updateSetting('clearTabsBtn', {
            ...clearTabsBtn,
            options: updatedOptions
        });
        await sendRuntimeMessage("update_setting", {
            key: "clearTabsBtn",
            value: {
                ...clearTabsBtn,
                options: updatedOptions
            }
        });
    };

    return (
        <Grid container alignItems="center">
            <Grid item xs={8}>
                <Typography variant="h3" mb={1}>{t("label")}</Typography>
                <Typography variant="body1" color='text.secondary'>{t("description")}</Typography>
            </Grid>
            <Grid item xs={2}>
                <FormControlLabel control={<Switch color="error" checked={clearTabsBtn.enable}
                    onChange={handleEnableChange} />}
                    labelPlacement="start"
                />
            </Grid>
            {clearTabsBtn.enable &&
                <Grid item xs={2}>
                    <Button size="small" endIcon={<ArrowRight />} variant="text" color="error" onClick={handleMoreOptionsClick}>
                        {t('configure')}
                    </Button>
                </Grid>
            }

            <Dialog open={open} onClose={(event, reason) => { if (reason !== 'backdropClick') { handleDialogClose() } }}>
                <DialogTitle variant="h3">{t('configure')}</DialogTitle>
                <DialogContent>
                    <FormLabel component="h4">{t("configureDesc")}</FormLabel>
                    <FormGroup>
                        {options.map(option => (
                            <FormControlLabel
                                key={option.key}
                                control={
                                    <Checkbox
                                        color="error"
                                        checked={option.value}
                                        onChange={handleOptionChange}
                                        name={option.key}
                                    />
                                }
                                label={option.label}
                            />
                        ))}
                    </FormGroup>
                </DialogContent>
                <DialogActions>
                    <Button onClick={handleDialogClose} color="error">
                        {t('close')}
                    </Button>
                </DialogActions>
            </Dialog>
        </Grid>
    );
}