import React, { useContext } from "react";
import { userStore } from "../../../../core/stores/userStore";
import { useTranslationContext } from "../../../Providers/TranslationProvider";

import { FormControlLabel, Grid, Switch, Typography } from "@mui/material";
import { sendRuntimeMessage } from "../../../../core/browers/runtime";



export default function AutoScrollToActiveTab() {
    const { t } = useTranslationContext("translation", { keyPrefix: "" });

    const { updateSetting, autoScrollToActiveTab } = userStore((state) => ({
        updateSetting: state.updateSetting,
        autoScrollToActiveTab: state.settings.autoScrollToActiveTab
    }));



    const handleChange = async (event) => {
        await updateSetting('autoScrollToActiveTab', event.target.checked)
        await sendRuntimeMessage("update_setting", { key: "autoScrollToActiveTab", value: event.target.checked })
    }


    return (

        <Grid container alignItems="center" >
            <Grid item xs={8}>
                <Typography variant="h3" mb={1}>{t("ScrollToActiveTab")}</Typography>
                <Typography variant="body1" color='text.secondary'> </Typography>
            </Grid>
            <Grid item xs={4}>
                <FormControlLabel control={<Switch color="error" checked={autoScrollToActiveTab}
                    onChange={handleChange} />}
                    labelPlacement="start"

                />
            </Grid>
        </Grid>

    )

}
