import React, { useEffect, useState } from 'react';
import snapshotStore from '../../../../core/stores/snapshotStore';
import { Container, Button, Stack, Checkbox, FormControlLabel } from '@mui/material';
import WindowItem from './WindowItem';
import { formatDateYmdHis } from '../../../../utils/helpers';
import { useTranslationContext } from "../../../Providers/TranslationProvider";
const SnapshotDetails = () => {
    const { t } = useTranslationContext('options', { keyPrefix: 'snapshots' });

    const { selectedTabs, selectedTabsCount, selectdSnapshotId } = snapshotStore((state) => ({
        selectedTabs: state.selectedTabs,
        selectedTabsCount: Object.values(state.selectedTabs).flat().length,
        selectdSnapshotId: state.selectdSnapshotId
    }));

    const [snapshotDetails, setSnapshotDetails] = useState(null);
    const [restoreWindowSize, setRestoreWindowSize] = useState(true);
    const [restoreGroups, setRestoreGroups] = useState(true);

    useEffect(() => {
        const fetchDetails = async () => {
            if (selectdSnapshotId) {
                const details = await snapshotStore.getState().fetchSnapshot(selectdSnapshotId);
                setSnapshotDetails(details);
            }
        };

        fetchDetails();
    }, [selectdSnapshotId]);

    const handleOpenWindow = () => {
        if (snapshotDetails) {
            snapshotDetails.windows.forEach(window => {
                const selectdWindowTabs = selectedTabs[window.id] || [];
                const tabsToOpen = selectdWindowTabs.length > 0
                    ? window.tabs.filter(tab => selectdWindowTabs.includes(tab.id))
                    : window.tabs;

                // 按分组整理标签页
                const groupedTabs = {};
                const ungroupedTabs = [];

                tabsToOpen.forEach(tab => {
                    if (restoreGroups && tab.groupId && tab.groupId !== -1) {
                        if (!groupedTabs[tab.groupId]) {
                            groupedTabs[tab.groupId] = [];
                        }
                        groupedTabs[tab.groupId].push(tab);
                    } else {
                        ungroupedTabs.push(tab);
                    }
                });

                // 创建窗口并打开第一个标签
                const firstTab = tabsToOpen[0];
                const createWindowOptions = {
                    url: firstTab.url,
                    ...(restoreWindowSize && {
                        left: window.left,
                        top: window.top,
                        width: window.width,
                        height: window.height
                    })
                };

                chrome.windows.create(createWindowOptions, (newWindow) => {
                    let delay = 0;
                    const groupTabIds = {};

                    // 先创建分组内的标签
                    Object.entries(groupedTabs).forEach(([groupId, tabs]) => {
                        const parsedGroupId = parseInt(groupId);
                        const group = window.tabGroups?.find(g => g.id === parsedGroupId);
                        groupTabIds[parsedGroupId] = [];

                        tabs.forEach((tab, index) => {
                            setTimeout(() => {
                                chrome.tabs.create({
                                    windowId: newWindow.id,
                                    url: tab.url,
                                    active: false
                                }, (createdTab) => {
                                    groupTabIds[parsedGroupId].push(createdTab.id);

                                    // 当分组内所有标签都创建完成时，创建分组
                                    if (groupTabIds[parsedGroupId].length === tabs.length) {
                                        chrome.tabs.group({
                                            tabIds: groupTabIds[parsedGroupId],
                                            createProperties: { windowId: newWindow.id }
                                        }, (newGroupId) => {
                                            if (group) {
                                                chrome.tabGroups.update(newGroupId, {
                                                    color: group.color,
                                                    title: group.title
                                                });
                                            }
                                        });
                                    }
                                });
                            }, delay);
                            delay += 250;
                        });
                    });

                    // 然后创建未分组的标签
                    ungroupedTabs.forEach((tab) => {
                        setTimeout(() => {
                            chrome.tabs.create({
                                windowId: newWindow.id,
                                url: tab.url,
                                active: false
                            });
                        }, delay);
                        delay += 250;
                    });
                });
            });
        }
    };

    const handleOpenInCurrentWindow = () => {
        if (snapshotDetails) {
            let delay = 0;
            const groupTabIds = {};

            snapshotDetails.windows.forEach(window => {
                const selectdWindowTabs = selectedTabs[window.id] || [];
                if (selectdWindowTabs.length > 0) {
                    const tabsToOpen = window.tabs.filter(tab => selectdWindowTabs.includes(tab.id));

                    // 按分组整理标签页
                    const groupedTabs = {};
                    const ungroupedTabs = [];

                    tabsToOpen.forEach(tab => {
                        if (restoreGroups && tab.groupId && tab.groupId !== -1) {
                            if (!groupedTabs[tab.groupId]) {
                                groupedTabs[tab.groupId] = [];
                            }
                            groupedTabs[tab.groupId].push(tab);
                        } else {
                            ungroupedTabs.push(tab);
                        }
                    });

                    // 先创建分组内的标签
                    Object.entries(groupedTabs).forEach(([groupId, tabs]) => {
                        const parsedGroupId = parseInt(groupId);
                        const group = window.tabGroups?.find(g => g.id === parsedGroupId);
                        groupTabIds[parsedGroupId] = [];

                        tabs.forEach(tab => {
                            setTimeout(() => {
                                chrome.tabs.create({
                                    url: tab.url,
                                    active: false
                                }, (createdTab) => {
                                    groupTabIds[parsedGroupId].push(createdTab.id);

                                    // 当分组内所有标签都创建完成时，创建分组
                                    if (groupTabIds[parsedGroupId].length === tabs.length) {
                                        chrome.tabs.group({
                                            tabIds: groupTabIds[parsedGroupId]
                                        }, (newGroupId) => {
                                            if (group) {
                                                chrome.tabGroups.update(newGroupId, {
                                                    color: group.color,
                                                    title: group.title
                                                });
                                            }
                                        });
                                    }
                                });
                            }, delay);
                            delay += 250;
                        });
                    });

                    // 然后创建未分组的标签
                    ungroupedTabs.forEach(tab => {
                        setTimeout(() => {
                            chrome.tabs.create({
                                url: tab.url,
                                active: false
                            });
                        }, delay);
                        delay += 250;
                    });
                }
            });
        }
    };

    const handleExportSnapshot = () => {
        if (snapshotDetails) {
            const dataStr = "data:text/json;charset=utf-8," + encodeURIComponent(JSON.stringify(snapshotDetails));
            const downloadAnchorNode = document.createElement('a');
            const formattedDate = formatDateYmdHis(snapshotDetails.createdAt);
            downloadAnchorNode.setAttribute("href", dataStr);
            downloadAnchorNode.setAttribute("download", `snapshot_${formattedDate}.json`);
            document.body.appendChild(downloadAnchorNode);
            downloadAnchorNode.click();
            downloadAnchorNode.remove();
        }
    };

    const handleCheckboxChange = (event) => {
        setRestoreWindowSize(event.target.checked);
    };

    const handleGroupsCheckboxChange = (event) => {
        setRestoreGroups(event.target.checked);
    };

    if (!selectdSnapshotId) {
        return null;
    }

    return (
        <Container>
            <Stack direction="row" justifyContent="flex-end" sx={{ marginBottom: 2 }} spacing={2}>
                <FormControlLabel
                    control={<Checkbox checked={restoreWindowSize} onChange={handleCheckboxChange} />}
                    label={t('restoreWindowSize')}
                />
                <FormControlLabel
                    control={<Checkbox checked={restoreGroups} onChange={handleGroupsCheckboxChange} />}
                    label={t('restoreGroups')}
                />
                <Button variant="outlined" color="error" onClick={handleExportSnapshot}>{t('exportSnapshot')}</Button>
                <Button variant="outlined" color="error" onClick={handleOpenWindow}>
                    {selectedTabsCount > 0 ? `${t('openSelectedInNewWindow')} (${selectedTabsCount})` : t('openAllWindows')}
                </Button>
                {selectedTabsCount > 0 && (
                    <Button variant="outlined" color="error" onClick={handleOpenInCurrentWindow}>
                        {t('openSelectedInCurrentWindow')} ({selectedTabsCount})
                    </Button>
                )}
            </Stack>
            {snapshotDetails?.windows.map((window, windowIndex) => (
                <WindowItem
                    key={windowIndex}
                    window={window}
                    windowIndex={windowIndex}
                    restoreWindowSize={restoreWindowSize}
                    restoreGroups={restoreGroups}
                />
            ))}
        </Container>
    );
};

export default SnapshotDetails;
