import React from 'react';
import {
    Card,
    CardContent,
    FormControlLabel,
    Switch,
    Typography,
    TextField,
    Grid,
    Stack
} from '@mui/material';
import { useTranslationContext } from '../../../../Providers/TranslationProvider';
import userStore from '../../../../../core/stores/userStore';
import { SYNC } from '../../../../../configs/app';
import { sendRuntimeMessage } from '../../../../../core/browers/runtime';

const GlobalTriggers = ({ syncMode }) => {
    const { t } = useTranslationContext('options', { keyPrefix: 'settings.syncToCloud.globalTriggers' });

    const { updateSetting, syncConfig, isUserLoggedIn } = userStore((state) => ({
        updateSetting: state.updateSetting,
        syncConfig: state.settings.syncConfig,
        isUserLoggedIn: !!state.userInfo?.id

    }));

    const handleSwitchChange = (key) => async (event) => {
        const newSyncConfig = {
            ...syncConfig,
            globalTriggers: {
                ...syncConfig.globalTriggers,
                [key]: { enabled: event.target.checked }
            }
        };
        await updateSetting('syncConfig', newSyncConfig);
        await sendRuntimeMessage("update_setting", {
            key: "syncConfig",
            value: newSyncConfig
        });

    };


    const isDisabled = syncMode === SYNC.MODES.DISABLED || !isUserLoggedIn;

    return (
        <Grid container alignItems="flex-start">
            <Grid item xs={6}>
                <Typography variant="h3" mb={1}>{t('title')}</Typography>
                <Typography variant="body1" color="text.secondary">
                    {t('description')}
                </Typography>
            </Grid>
            <Grid item xs={6}>
                <Stack>
                    <FormControlLabel
                        control={
                            <Switch
                                color='error'
                                checked={syncConfig.globalTriggers.onStartup.enabled}
                                onChange={handleSwitchChange('onStartup')}
                                disabled={isDisabled}
                            />
                        }
                        label={t('onStartup')}
                    />

                </Stack>
            </Grid>
        </Grid>
    );
};

export default GlobalTriggers;
