import { httpRequestJSON } from "./http";

const timeCache = {
    timestamp: 0,     // 本地请求时间戳
    offset: 0,        // 服务器和本地的时间差
    TTL: 3000,        // 缓存时间 3 秒
    pendingPromise: null  // 添加一个 Promise 来处理并发请求
};

/**
 * 获取服务器时间
 * @param {string} serverTimeApi - 服务器时间API地址
 * @returns {Promise<number>} 服务器时间戳
 */
export async function getServerTime(serverTimeApi) {
    const now = Date.now();

    // 如果缓存未过期，使用时间差计算当前服务器时间
    if (now - timeCache.timestamp < timeCache.TTL) {
        return now + timeCache.offset;
    }

    // 如果已经有一个请求在进行中，返回同一个 Promise
    if (timeCache.pendingPromise) {
        return timeCache.pendingPromise;
    }

    try {
        // 创建新的 Promise 并保存
        timeCache.pendingPromise = (async () => {
            const startTime = Date.now();
            const response = await httpRequestJSON({
                url: serverTimeApi,
                method: 'get',
                timeout: 3000
            });

            const serverTime = response?.data?.now;
            if (!serverTime || typeof serverTime !== 'number') {
                return now;
            }

            const networkLatency = (Date.now() - startTime) / 2;
            const adjustedServerTime = serverTime + networkLatency;

            timeCache.timestamp = now;
            timeCache.offset = adjustedServerTime - now;

            return adjustedServerTime;
        })();

        const result = await timeCache.pendingPromise;
        return result;
    } catch (error) {
        console.warn('Failed to fetch server time:', error);
        return now;
    } finally {
        // 清除 pendingPromise
        timeCache.pendingPromise = null;
    }
}