import { recordDebugLog } from '../../../utils/helpers';
import { addCachedHistory, localCacheHistoriesInstance } from '../../stores/historyStore';

/**
 * Retrieves recent closed tabs data from local cache
 * @returns {Promise<Array|null>} Array of recent closed tabs or null if error
 */
export async function getRecentClosedTabsData() {
    try {
        const recentlyTabsInstance = await localCacheHistoriesInstance();
        if (!recentlyTabsInstance) {
            recordDebugLog('[syncService] [recentClosedTabs] Failed to get recently tabs instance');
            return null;
        }
        return await recentlyTabsInstance.all();
    } catch (error) {
        recordDebugLog(`[syncService] [recentClosedTabs] Failed to get recent closed tabs data: ${error.message}`);
        return null;
    }
}

/**
 * Applies recent closed tabs data from cache
 * @param {string} dataKey - Key to retrieve data from cache
 * @param {Object} localCache - Local cache instance
 * @returns {Promise<void>}
 */
export async function applyRecentClosedTabs(dataKey, localCache) {
    if (!dataKey || !localCache) {
        recordDebugLog(`[syncService] [${dataKey}] Invalid parameters for applying recent closed tabs`, dataKey);
        return;
    }

    try {
        const cachedData = await localCache.get(dataKey);

        if (!cachedData?.items?.length) {
            recordDebugLog(`[syncService] [${dataKey}] No valid recent closed tabs data to apply`, dataKey);
            return;
        }

        // Process items in batches to avoid overwhelming the system
        const batchSize = 50;
        for (let i = 0; i < cachedData.items.length; i += batchSize) {
            const batch = cachedData.items.slice(i, i + batchSize);
            await Promise.all(batch.map(item => addCachedHistory(item)));
        }

        recordDebugLog(`[syncService] [${dataKey}] Successfully applied ${cachedData.items.length} recent closed tabs`, dataKey);
    } catch (error) {
        recordDebugLog(`[syncService] [${dataKey}] Failed to apply recent closed tabs: ${error.message}`, dataKey);
        throw error;
    }
}