import React from "react";
import { Box, Button, Paper, Stack, Typography, Chip } from "@mui/material";
import WindowTabItem from "./WindowTabItem";
import snapshotStore from "../../../../core/stores/snapshotStore";
import { useTranslationContext } from "../../../Providers/TranslationProvider";
import ClearIcon from '@mui/icons-material/Clear';
import OpenInNewIcon from '@mui/icons-material/OpenInNew';
import LaunchIcon from '@mui/icons-material/Launch';
import { chromeGroupAvailableColors } from "../../../../utils/colors";
import { colord } from "colord";
import Checkbox from '@mui/material/Checkbox';

// Helper function to create tabs with delay
async function createTabsInWindow(tabs, windowId, options = {}) {
    const groupTabs = {};
    const createdTabs = [];

    for (const tab of tabs) {
        try {
            const createdTab = await chrome.tabs.create({
                windowId,
                url: tab.url,
                active: false,
                pinned: tab.pinned,
                index: tab.index,
            });

            createdTabs.push(createdTab);

            // 处理已丢弃的标签页
            if (tab.discarded) {
                const discardListener = (tabId, changeInfo) => {
                    if (tabId === createdTab.id && changeInfo.status === 'complete') {
                        chrome.tabs.discard(createdTab.id);
                        chrome.tabs.onUpdated.removeListener(discardListener);
                    }
                };
                chrome.tabs.onUpdated.addListener(discardListener);
            }

            // 收集需要分组的标签页
            if (options.restoreGroups && tab.groupId > 0) {
                if (!groupTabs[tab.groupId]) {
                    groupTabs[tab.groupId] = [];
                }
                groupTabs[tab.groupId].push(createdTab.id);
            }

            // 添加小延迟避免过快创建标签页
            await new Promise(resolve => setTimeout(resolve, 100));
        } catch (error) {
            console.error('Error creating tab:', error, tab);
        }
    }

    return { groupTabs, createdTabs };
}

// Helper function to create and update tab groups
async function createTabGroups(groupTabs, snapshotWindow, windowId) {
    for (const [groupId, tabIds] of Object.entries(groupTabs)) {
        if (tabIds.length === 0) continue;

        const group = snapshotWindow.tabGroups?.find(g => g.id === parseInt(groupId));
        if (!group) continue;

        try {
            // 创建新组
            const newGroupId = await chrome.tabs.group({
                tabIds,
                createProperties: { windowId }
            });

            // 更新组的属性
            await chrome.tabGroups.update(newGroupId, {
                collapsed: group.collapsed,
                color: group.color,
                title: group.title
            });

            // 添加小延迟避免过快更新组
            await new Promise(resolve => setTimeout(resolve, 100));
        } catch (error) {
            console.error('Error creating/updating tab group:', error, { groupId, tabIds });
        }
    }
}

const WindowItem = React.memo(({ windowIndex, window: snapshotWindow, restoreWindowSize, restoreGroups }) => {
    const { t } = useTranslationContext('options', { keyPrefix: 'snapshots' });

    const { selectdWindowTabs, selectedTabsCount, selectedTabs, selectedGroups } = snapshotStore((state) => ({
        selectdWindowTabs: state.selectedTabs[snapshotWindow.id] || [],
        selectedTabsCount: (state.selectedTabs[snapshotWindow.id] || []).length,
        selectedTabs: state.selectedTabs,
        selectedGroups: state.selectedGroups[snapshotWindow.id] || [],
    }));

    // Group tabs by groupId
    const groupedTabs = React.useMemo(() => {
        const groups = {};
        snapshotWindow.tabs.forEach(tab => {
            const groupId = tab.groupId && tab.groupId !== -1 ? tab.groupId : 'ungrouped';
            if (!groups[groupId]) groups[groupId] = [];
            groups[groupId].push(tab);
        });
        return groups;
    }, [snapshotWindow.tabs]);

    // Color mapping for tab groups
    const colorMapping = React.useMemo(() => {
        return chromeGroupAvailableColors.reduce((acc, colorInfo) => {
            const baseColor = colorInfo.hex;
            acc[colorInfo.tabGroupColor] = {
                light: colord(baseColor).alpha(0.08).toRgbString(),
                main: colord(baseColor).alpha(0.3).toRgbString(),
                dark: colord(baseColor).alpha(0.9).toRgbString()
            };
            return acc;
        }, {});
    }, []);

    function handleGroupSelection(groupId, tabs) {
        const isSelected = selectedGroups.includes(groupId);

        snapshotStore.setState(state => {
            const newSelectedTabs = { ...state.selectedTabs };
            const newSelectedGroups = { ...state.selectedGroups };

            if (!newSelectedTabs[snapshotWindow.id]) newSelectedTabs[snapshotWindow.id] = [];
            if (!newSelectedGroups[snapshotWindow.id]) newSelectedGroups[snapshotWindow.id] = [];

            if (isSelected) {
                newSelectedTabs[snapshotWindow.id] = newSelectedTabs[snapshotWindow.id]
                    .filter(id => !tabs.find(tab => tab.id === id));
                newSelectedGroups[snapshotWindow.id] = newSelectedGroups[snapshotWindow.id]
                    .filter(id => id !== groupId);
            } else {
                const updatedTabs = [...newSelectedTabs[snapshotWindow.id]];
                tabs.forEach(tab => {
                    if (!updatedTabs.includes(tab.id)) {
                        updatedTabs.push(tab.id);
                    }
                });
                newSelectedTabs[snapshotWindow.id] = updatedTabs;
                newSelectedGroups[snapshotWindow.id] = [...newSelectedGroups[snapshotWindow.id], groupId];
            }

            return {
                ...state,
                selectedTabs: newSelectedTabs,
                selectedGroups: newSelectedGroups
            };
        });
    }

    async function handleOpenWindow() {
        let tabsToOpen = snapshotWindow.tabs.filter(tab => {
            const hasGroup = tab.groupId && tab.groupId !== -1;
            return selectdWindowTabs.includes(tab.id) ||
                (hasGroup && selectedGroups.includes(tab.groupId));
        });

        if (tabsToOpen.length === 0) {
            tabsToOpen = [...snapshotWindow.tabs];
        }

        // 按原始索引排序
        tabsToOpen.sort((a, b) => (a.index ?? Infinity) - (b.index ?? Infinity));

        try {
            // 1. 用第一个标签页创建窗口，避免出现空白新标签页
            const newWindow = await chrome.windows.create({
                url: tabsToOpen[0].url,
                focused: true,
                ...(restoreWindowSize && {
                    left: snapshotWindow.left,
                    top: snapshotWindow.top,
                    width: snapshotWindow.width,
                    height: snapshotWindow.height
                })
            });

            // 2. 创建其余标签页
            const { groupTabs, createdTabs } = await createTabsInWindow(
                tabsToOpen.slice(1), // 跳过第一个标签页
                newWindow.id,
                { restoreGroups }
            );

            // 3. 如果第一个标签页需要加入组，将其添加到 groupTabs 中
            if (restoreGroups && tabsToOpen[0].groupId > 0) {
                const firstTabId = newWindow.tabs[0].id;
                const groupId = tabsToOpen[0].groupId;
                if (!groupTabs[groupId]) {
                    groupTabs[groupId] = [];
                }
                groupTabs[groupId].push(firstTabId);
            }

            // 4. 如果需要恢复组，等待所有标签页创建完成后再创建组
            if (restoreGroups && Object.keys(groupTabs).length > 0) {
                await new Promise(resolve => setTimeout(resolve, 250));
                await createTabGroups(groupTabs, snapshotWindow, newWindow.id);
            }

        } catch (error) {
            console.error('Error opening window:', error);
        }
    }

    async function handleOpenInCurrentWindow() {
        // Get current window first
        const currentWindow = await chrome.windows.getCurrent();
        if (!currentWindow) return;

        const tabsToOpen = selectdWindowTabs.length > 0
            ? snapshotWindow.tabs.filter(tab => selectdWindowTabs.includes(tab.id) ||
                (tab.groupId && tab.groupId !== -1 && selectedGroups.includes(tab.groupId)))
            : snapshotWindow.tabs;

        tabsToOpen.sort((a, b) => (a.index ?? Infinity) - (b.index ?? Infinity));

        const { groupTabs } = await createTabsInWindow(tabsToOpen, currentWindow.id, { restoreGroups });

        if (restoreGroups && Object.keys(groupTabs).length > 0) {
            await createTabGroups(groupTabs, snapshotWindow);
        }
    }

    function handleResetSelection() {
        snapshotStore.setState(state => ({
            ...state,
            selectedTabs: {
                ...state.selectedTabs,
                [snapshotWindow.id]: []
            },
            selectedGroups: {
                ...state.selectedGroups,
                [snapshotWindow.id]: []
            }
        }));
    }

    function renderGroup(groupId, tabs) {
        if (groupId === 'ungrouped') {
            return (
                <Box key="ungrouped" sx={{ p: 0.5 }}>
                    {tabs.map((tab, tabIndex) => (
                        <WindowTabItem
                            key={tab.id}
                            tabIndex={tabIndex}
                            item={{
                                ...tab,
                                windowId: snapshotWindow.id
                            }}
                        />
                    ))}
                </Box>
            );
        }

        const group = snapshotWindow.tabGroups?.find(g => g.id === parseInt(groupId));
        if (!group) return null;

        const colors = colorMapping[group.color] || colorMapping.grey;
        const parsedGroupId = parseInt(groupId);
        const isGroupSelected = selectedGroups.includes(parsedGroupId);

        const selectedTabsInGroup = tabs.filter(tab =>
            selectedTabs[snapshotWindow.id]?.includes(tab.id)
        ).length;
        const allTabsSelected = selectedTabsInGroup === tabs.length;
        const someTabsSelected = selectedTabsInGroup > 0;

        return (
            <Box key={groupId} sx={{
                mb: 0.5,
                p: 0.5,
                borderRadius: 1,
                backgroundColor: colors.light,
                border: '1px solid',
                borderColor: colors.main,
                '&:hover': {
                    borderColor: colors.dark,
                }
            }}>
                <Stack direction="row" spacing={0.5} alignItems="center" sx={{ mb: 0.25, pl: 0.25 }}>
                    <Checkbox
                        size="small"
                        checked={isGroupSelected || allTabsSelected}
                        indeterminate={!isGroupSelected && someTabsSelected && !allTabsSelected}
                        onChange={() => handleGroupSelection(parsedGroupId, tabs)}
                        onClick={(e) => e.stopPropagation()}
                        sx={{
                            p: 0.25,
                            color: colors.dark,
                            '& .MuiSvgIcon-root': { fontSize: 18 }
                        }}
                    />
                    <Typography
                        variant="body2"
                        sx={{
                            fontWeight: 500,
                            color: colors.dark
                        }}
                    >
                        {group.title || t('untitledGroup')}
                    </Typography>
                    <Typography
                        variant="caption"
                        sx={{
                            color: colors.dark,
                            opacity: 0.7
                        }}
                    >
                        ({tabs.length})
                    </Typography>
                </Stack>
                <Box sx={{ pl: 4 }}>
                    {tabs.map((tab, tabIndex) => (
                        <WindowTabItem
                            key={tab.id}
                            tabIndex={tabIndex}
                            item={{
                                ...tab,
                                groupId: parsedGroupId,
                                windowId: snapshotWindow.id
                            }}
                        />
                    ))}
                </Box>
            </Box>
        );
    }

    return (
        <Paper
            elevation={1}
            sx={{
                mb: 1,
                borderRadius: 1,
                overflow: 'hidden',
                border: '1px solid',
                borderColor: 'divider'
            }}
        >
            <Box sx={{
                py: 0.5,
                px: 1,
                borderBottom: '1px solid',
                borderColor: 'divider',
                backgroundColor: 'background.default'
            }}>
                <Stack direction="row" justifyContent="space-between" alignItems="center" spacing={1}>
                    <Stack direction="row" spacing={0.5} alignItems="center">
                        <Typography
                            variant="subtitle2"
                            sx={{
                                fontSize: '0.875rem',
                                fontWeight: 600
                            }}
                        >
                            {t('Window')} {windowIndex + 1}
                        </Typography>
                        <Chip
                            size="small"
                            label={t('tabCount', { count: snapshotWindow.tabs.length })}
                            sx={{
                                height: 18,
                                '& .MuiChip-label': {
                                    px: 0.75,
                                    fontSize: '0.75rem'
                                }
                            }}
                        />
                    </Stack>
                    <Stack direction="row" spacing={0.5}>
                        {selectedTabsCount > 0 && (
                            <Button
                                size="small"
                                startIcon={<ClearIcon sx={{ fontSize: 16 }} />}
                                onClick={handleResetSelection}
                                sx={{
                                    py: 0.25,
                                    px: 0.75,
                                    minHeight: 0,
                                    fontSize: '0.75rem'
                                }}
                            >
                                {t('ResetSelection')}
                            </Button>
                        )}
                        <Button
                            size="small"
                            variant="outlined"
                            startIcon={<OpenInNewIcon />}
                            onClick={handleOpenInCurrentWindow}
                            sx={{ py: 0.5 }}
                        >
                            {t('OpenInCurrentWindow')} {selectedTabsCount ? `(${selectedTabsCount})` : ''}
                        </Button>
                        <Button
                            size="small"
                            variant="contained"
                            startIcon={<LaunchIcon />}
                            onClick={handleOpenWindow}
                            sx={{ py: 0.5 }}
                        >
                            {t('OpenInNewWindow')} {selectedTabsCount ? `(${selectedTabsCount})` : ''}
                        </Button>
                    </Stack>
                </Stack>
            </Box>
            <Box sx={{ p: 0.5 }}>
                {/* Render grouped tabs first */}
                {Object.entries(groupedTabs).map(([groupId, tabs]) => {
                    if (groupId === 'ungrouped') return null;
                    return renderGroup(groupId, tabs);
                })}

                {/* Then render ungrouped tabs */}
                {groupedTabs['ungrouped'] && renderGroup('ungrouped', groupedTabs['ungrouped'])}
            </Box>
        </Paper>
    );
});

export default WindowItem;