export const ERROR_CODES = {
    // 配置相关错误
    CONFIG_MISSING: 'CONFIG_MISSING',
    CONFIG_INVALID: 'CONFIG_INVALID',
    PROVIDER_UNSUPPORTED: 'PROVIDER_UNSUPPORTED',
    INVALID_SYNC_MODE: 'INVALID_SYNC_MODE',

    // 权限相关错误
    PERMISSION_DENIED: 'PERMISSION_DENIED',
    NOT_INITIALIZED: 'NOT_INITIALIZED',

    // 验证相关错误
    SYNC_DISABLED: 'SYNC_DISABLED',
    DATA_TYPE_DISABLED: 'DATA_TYPE_DISABLED',
    INVALID_DATA_TYPE: 'INVALID_DATA_TYPE',

    // 数据处理错误
    PROCESS_COMPRESS_ERROR: 'PROCESS_COMPRESS_ERROR',
    PROCESS_DECOMPRESS_ERROR: 'PROCESS_DECOMPRESS_ERROR',
    PROCESS_ENCRYPT_ERROR: 'PROCESS_ENCRYPT_ERROR',
    PROCESS_DECRYPT_ERROR: 'PROCESS_DECRYPT_ERROR',

    // 同步操作错误
    SYNC_UPLOAD_ERROR: 'SYNC_UPLOAD_ERROR',
    SYNC_DOWNLOAD_ERROR: 'SYNC_DOWNLOAD_ERROR',
    SYNC_MERGE_ERROR: 'SYNC_MERGE_ERROR',
    SYNC_UPDATE_METADATA_ERROR: 'SYNC_UPDATE_METADATA_ERROR',
    SYNC_DELETE_METADATA_ERROR: 'SYNC_DELETE_METADATA_ERROR',
    SYNC_CLEAN_ERROR: 'SYNC_CLEAN_ERROR',

    // 存储相关错误
    STORAGE_READ_ERROR: 'STORAGE_READ_ERROR',
    STORAGE_WRITE_ERROR: 'STORAGE_WRITE_ERROR',

    // 网络相关错误
    NETWORK_ERROR: 'NETWORK_ERROR',

    // 其他错误
    UNKNOWN_ERROR: 'UNKNOWN_ERROR',

    // 用户验证相关错误
    NOT_LOGGED_IN: 'NOT_LOGGED_IN',
    NO_LOCAL_PASSWORD: 'NO_LOCAL_PASSWORD',
    NOT_MEMBER: 'NOT_MEMBER',

    // 添加新的错误消息
    INIT_FAILED: 'INIT_FAILED',
    INIT_TIMEOUT: 'INIT_TIMEOUT',
};

const ERROR_MESSAGES = {
    [ERROR_CODES.CONFIG_MISSING]: 'Config is required for SyncService',
    [ERROR_CODES.CONFIG_INVALID]: 'Invalid configuration provided',
    [ERROR_CODES.PROVIDER_UNSUPPORTED]: 'Unsupported provider type: {provider}',
    [ERROR_CODES.INVALID_SYNC_MODE]: 'Invalid sync mode specified: {mode}',

    [ERROR_CODES.PERMISSION_DENIED]: 'User cannot sync - missing required permissions',
    [ERROR_CODES.NOT_INITIALIZED]: 'SyncService is not initialized',

    [ERROR_CODES.SYNC_DISABLED]: 'Sync mode is disabled',
    [ERROR_CODES.DATA_TYPE_DISABLED]: 'Data type is not enabled for sync: {dataType}',
    [ERROR_CODES.INVALID_DATA_TYPE]: 'Invalid data type: {dataType}',

    [ERROR_CODES.PROCESS_COMPRESS_ERROR]: 'Failed to compress data: {message}',
    [ERROR_CODES.PROCESS_DECOMPRESS_ERROR]: 'Failed to decompress data: {message}',
    [ERROR_CODES.PROCESS_ENCRYPT_ERROR]: 'Failed to encrypt data: {message}',
    [ERROR_CODES.PROCESS_DECRYPT_ERROR]: 'Failed to decrypt data: {message}',

    [ERROR_CODES.SYNC_UPLOAD_ERROR]: 'Failed to upload {dataType}: {message}',
    [ERROR_CODES.SYNC_DOWNLOAD_ERROR]: 'Failed to download {dataType}: {message}',
    [ERROR_CODES.SYNC_MERGE_ERROR]: 'Failed to merge {dataType}: {message}',
    [ERROR_CODES.SYNC_UPDATE_METADATA_ERROR]: 'Failed to update metadata for {dataType}: {message}',
    [ERROR_CODES.SYNC_DELETE_METADATA_ERROR]: 'Failed to delete metadata for {dataType}: {message}',
    [ERROR_CODES.SYNC_CLEAN_ERROR]: 'Failed to clean server data: {message}',

    [ERROR_CODES.STORAGE_READ_ERROR]: 'Failed to read from storage: {message}',
    [ERROR_CODES.STORAGE_WRITE_ERROR]: 'Failed to write to storage: {message}',

    [ERROR_CODES.NETWORK_ERROR]: 'Network error: {message}',
    [ERROR_CODES.UNKNOWN_ERROR]: 'Unknown error occurred: {message}',

    // 用户验证相关错误消息
    [ERROR_CODES.NOT_LOGGED_IN]: 'User is not logged in',
    [ERROR_CODES.NO_LOCAL_PASSWORD]: 'Local password is not set',
    [ERROR_CODES.NOT_MEMBER]: 'User is not a member',

    // 添加新的错误消息
    [ERROR_CODES.INIT_FAILED]: 'Service initialization failed: {message}',
    [ERROR_CODES.INIT_TIMEOUT]: 'Service initialization timed out after {timeout}ms',

    // 添加默认错误消息
    DEFAULT: 'An error occurred: {message}'
};

export class SyncError extends Error {
    constructor(code, details = {}, originalError = null) {
        // 获取错误消息，如果没有找到对应的消息则使用默认消息
        let message = ERROR_MESSAGES[code] || ERROR_MESSAGES.DEFAULT;

        // 安全地替换占位符
        if (details && typeof details === 'object') {
            Object.entries(details).forEach(([key, value]) => {
                const placeholder = `{${key}}`;
                if (message.includes(placeholder)) {
                    message = message.replace(placeholder, value);
                }
            });
        }

        // 移除任何未被替换的占位符
        message = message.replace(/\{[^}]+\}/g, '');

        super(message);
        this.name = 'SyncError';
        this.code = code;
        this.details = details;
        this.originalError = originalError;

        // 捕获堆栈跟踪
        if (Error.captureStackTrace) {
            Error.captureStackTrace(this, SyncError);
        }
    }

    is(code) {
        return this.code === code;
    }

    getFormattedMessage() {
        return `[${this.code}] ${this.message}`;
    }

    // 添加一个方法来获取完整的错误信息，包括原始错误
    getFullMessage() {
        let message = this.getFormattedMessage();
        if (this.originalError) {
            message += `\nOriginal error: ${this.originalError.message}`;
        }
        return message;
    }
}
