import React, { useEffect, useState } from 'react';
import {
    Box,
    Typography,
    Divider,
    Stack,
    Chip,
    Button,
    CircularProgress
} from '@mui/material';
import { green, red, grey } from '@mui/material/colors';
import ErrorIcon from '@mui/icons-material/Error';
import CloudUploadIcon from '@mui/icons-material/CloudUpload';
import CloudDownloadIcon from '@mui/icons-material/CloudDownload';
import userStore from '../../../../core/stores/userStore';
import { useTranslationContext } from '../../../Providers/TranslationProvider';
import SyncProvidersSection from './components/SyncProvidersSection';
import SyncModeSection from './components/SyncModeSection';
import SyncDataOptionsSection from './components/SyncDataOptionsSection';
import GlobalTriggers from './components/GlobalTriggers';
import DeviceName from './components/DeviceName';
import PasswordSetup from './components/PasswordSetup';
import { getUserConfig, hasLocalPassword, userPublicLocalStorage } from '../../../../core/user';
import { formatLocalTime, recordDebugLog } from '../../../../utils/helpers';
import { sendRuntimeMessage } from '../../../../core/browers/runtime';
import { toast } from 'react-toastify';
import PremiumBackdrop from '../../../component/PremiumBackdrop';
import { SYNC } from '../../../../configs/app';
import ChangeLocalPassword from './components/ChangeLocalPassword';

const SyncSettings = () => {
    const { t, language } = useTranslationContext('options', { keyPrefix: 'settings.syncToCloud' });

    const [lastSyncTime, setLastSyncTime] = useState('');
    const [uploadStatus, setUploadStatus] = useState('');
    const [downloadStatus, setDownloadStatus] = useState('');
    const [isPasswordSet, setIsPasswordSet] = useState(false);
    const [isSyncing, setIsSyncing] = useState(false);
    const [syncMode, setSyncMode] = useState('disabled');

    useEffect(() => {
        const checkPassword = async () => {
            const hasPassword = await hasLocalPassword();
            setIsPasswordSet(hasPassword);
        };
        checkPassword();
    }, []);

    useEffect(() => {
        const fetchSyncStatus = async () => {
            const localCache = await userPublicLocalStorage('sync');
            const lastSyncTime = await localCache.get('last_sync_at');
            const uploadStatus = await localCache.get('last_upload_status');
            const downloadStatus = await localCache.get('last_download_status');
            setLastSyncTime(lastSyncTime ? formatLocalTime(lastSyncTime, language.replace('_', '-')) : t('notSynced'));
            setUploadStatus(uploadStatus || 'notSynced');
            setDownloadStatus(downloadStatus || 'notSynced');
        };
        fetchSyncStatus();
    }, []);

    useEffect(() => {
        const loadSyncMode = async () => {
            const mode = await getUserConfig('syncMode');
            if (mode) {
                setSyncMode(mode);
            }
        };
        loadSyncMode();
    }, []);


    const handlePasswordStatusChange = (hasPassword) => {
        setIsPasswordSet(hasPassword);
    };

    const handleSyncNow = async () => {
        setIsSyncing(true);
        const response = await sendRuntimeMessage('sync_now');
        recordDebugLog("handleSyncNow response", response);
        if (!response.success && response.error) {
            toast.error(t(response.error, { ns: "error", keyPrefix: "" }));
        }
        await updateSyncStatus();
        setIsSyncing(false);
    };

    const updateSyncStatus = async () => {
        const localCache = await userPublicLocalStorage('sync');
        const lastSyncTime = await localCache.get('last_sync_at');
        const uploadStatus = await localCache.get('last_upload_status');
        const downloadStatus = await localCache.get('last_download_status');
        setLastSyncTime(lastSyncTime ? formatLocalTime(lastSyncTime, language.replace('_', '-')) : t('notSynced'));
        setUploadStatus(uploadStatus || 'notSynced');
        setDownloadStatus(downloadStatus || 'notSynced');
    };

    return (
        <Box>
            {/* <PasswordSetup onPasswordStatusChange={handlePasswordStatusChange} /> */}

            {/* {isPasswordSet && ( */}
            <>

                <Typography variant="h2" gutterBottom>
                    {t('title')}
                </Typography>
                <Divider textAlign="center" sx={{ color: "error.main", padding: "10px", my: 3 }}>{t('premiumEditionOnly', { keyPrefix: "settings" })}</Divider>
                <PremiumBackdrop>
                    <Stack direction='row' my={3} spacing={3} justifyContent='flex-end' alignItems='center'>
                        <Typography variant="h4">
                            {t('lastSyncTime')}: {lastSyncTime}
                        </Typography>
                        <Chip
                            label={`${t('uploadStatus')}: ${t(uploadStatus)}`}
                            icon={
                                uploadStatus === 'success' ? (
                                    <CloudUploadIcon color='success' />
                                ) : uploadStatus === 'failure' ? (
                                    <ErrorIcon />
                                ) : null
                            }
                            sx={{
                                backgroundColor: uploadStatus === 'success' ? `${green[500]}4D` : uploadStatus === 'failure' ? `${red[500]}4D` : `${grey[500]}4D`,
                                color: '#333',
                                fontSize: "9px",
                                display: 'flex',
                                alignItems: 'center',
                                paddingX: "4px",
                                ml: 1
                            }}
                        />
                        <Chip
                            label={`${t('downloadStatus')}: ${t(downloadStatus)}`}
                            icon={
                                downloadStatus === 'success' ? (
                                    <CloudDownloadIcon color='success' />
                                ) : downloadStatus === 'failure' ? (
                                    <ErrorIcon />
                                ) : null
                            }
                            sx={{
                                backgroundColor: downloadStatus === 'success' ? `${green[500]}4D` : downloadStatus === 'failure' ? `${red[500]}4D` : `${grey[500]}4D`,
                                color: '#333',
                                fontSize: "9px",
                                display: 'flex',
                                alignItems: 'center',
                                paddingX: "4px",
                                ml: 1
                            }}
                        />
                        <Button
                            variant='contained'
                            onClick={handleSyncNow}
                            color="error"
                            sx={{ ml: 2 }}
                            startIcon={isSyncing ? <CircularProgress size={20} /> : null}
                            disabled={isSyncing || syncMode === SYNC.MODES.DISABLED}
                        >
                            {t('syncNow')}
                        </Button>
                    </Stack>
                    <Stack spacing={3} divider={<Divider orientation="horizontal" flexItem />}>
                        <DeviceName />
                        <ChangeLocalPassword />
                        <SyncModeSection
                            syncMode={syncMode}
                            setSyncMode={setSyncMode}
                        />
                        {/* <SyncProvidersSection
                                syncMode={syncMode}
                            /> */}
                        <SyncDataOptionsSection
                            syncMode={syncMode}

                        />
                        <GlobalTriggers
                            syncMode={syncMode}
                        />
                    </Stack>
                </PremiumBackdrop>

            </>
            {/* )} */}
        </Box>
    );
};

export default SyncSettings;
