import React, { useState, useEffect } from 'react';
import { Grid, TextField, Typography, IconButton, Input, OutlinedInput } from '@mui/material';
import SaveIcon from '@mui/icons-material/Save';
import { useTranslationContext } from '../../../../Providers/TranslationProvider';
import userStore from '../../../../../core/stores/userStore';
import { getUserConfig, setUserConfig } from '../../../../../core/user';
import { getShortBrowserName } from '../../../../../utils/helpers';
import { sendRuntimeMessage } from '../../../../../core/browers/runtime';

const DeviceName = () => {
    const [deviceName, setDeviceName] = useState('');
    const [tempName, setTempName] = useState('');
    const { t } = useTranslationContext('options', { keyPrefix: 'settings.syncToCloud' });
    const { updateSetting, syncConfig } = userStore((state) => ({
        updateSetting: state.updateSetting,
        syncConfig: state.settings.syncConfig
    }));

    useEffect(() => {
        const loadDeviceName = async () => {
            let name = await getUserConfig('deviceName');
            if (!name) {
                name = getShortBrowserName();
                await setUserConfig('deviceName', name);
            }
            setDeviceName(name || '');
            setTempName(name || '');
        };
        loadDeviceName();
    }, []);

    const handleChange = (e) => {
        setTempName(e.target.value);
    };

    const handleSave = async () => {
        setDeviceName(tempName);
        await setUserConfig("deviceName", tempName);
        await sendRuntimeMessage('reset_sync_service');
    };

    return (
        <Grid container alignItems="center">
            <Grid item xs={12} md={6}>
                <Typography variant="h3" mb={1}>{t('deviceName')}</Typography>
                <Typography variant="body1" color="text.secondary" mb={1}>
                    {t('deviceNameDescription')}
                </Typography>
            </Grid>
            <Grid item xs={12} md={6} sx={{ display: 'flex', alignItems: 'center' }}>
                <OutlinedInput
                    value={tempName}
                    onChange={handleChange}
                    size="small"

                    sx={{ borderRadius: 1, minWidth: "200px" }}
                    endAdornment={<IconButton
                        onClick={handleSave}
                        disabled={tempName === deviceName}
                        sx={{ ml: 1 }}
                    >
                        <SaveIcon />
                    </IconButton>}
                />

            </Grid>
        </Grid>
    );
};

export default DeviceName;
