import React, { useEffect, useState } from 'react';
import { Box, Typography, Button, Grid, Paper, CircularProgress, Stack, Chip, Avatar, IconButton } from '@mui/material';
import { useTranslationContext } from '../../../Providers/TranslationProvider';
import { fetchUserInfo, getCurrentUserUUID, getUserInfo, userLogout } from '../../../../core/user';
import ExitToAppIcon from '@mui/icons-material/ExitToApp';
import CardGiftcardIcon from '@mui/icons-material/CardGiftcard';
import AccountCircleIcon from '@mui/icons-material/AccountCircle';
import RefreshIcon from '@mui/icons-material/Refresh';
import { sendRuntimeMessage } from '../../../../core/browers/runtime';
import userStore from '../../../../core/stores/userStore';

const AccountInfo = () => {

    const { language, t } = useTranslationContext("options", { keyPrefix: "settings.general.accountInfo" });

    const { setUser } = userStore((state) => ({
        setUser: state.setUser
    }))

    const [localUserInfo, setLocalUserInfo] = useState(null);
    const [isLoggingOut, setIsLoggingOut] = useState(false);
    const [isRefreshing, setIsRefreshing] = useState(false);

    useEffect(() => {
        const fetchUserData = async () => {
            const cachedInfo = await getUserInfo();
            setLocalUserInfo(cachedInfo);

            if (!cachedInfo) {
                const freshInfo = await fetchUserInfo();
                setLocalUserInfo(freshInfo);
                await setUser(freshInfo);
            }
        };

        fetchUserData();

        const handleExternalMessage = async (message, sender, sendResponse) => {
            if (message.action === 'user_login_success') {
                const freshInfo = await fetchUserInfo();
                setLocalUserInfo(freshInfo);
                await setUser(freshInfo);
                sendRuntimeMessage('reset_sync_service');
                // setTimeout(() => window.location.reload(), 500);
            }
            sendResponse({ success: true });
        };

        chrome.runtime.onMessageExternal.addListener(handleExternalMessage);

        return () => {
            chrome.runtime.onMessageExternal.removeListener(handleExternalMessage);
        };
    }, []);

    const isLoggedIn = !!localUserInfo?.email;

    const handleUserLogin = async () => {
        const { width, height } = window.screen;
        const popupWidth = 460;
        const popupHeight = 720;
        const left = Math.round((width - popupWidth) / 2);
        const top = Math.round((height - popupHeight) / 2);
        const device_id = await getCurrentUserUUID();
        chrome.windows.create({
            focused: true,
            setSelfAsOpener: true,
            width: popupWidth,
            height: popupHeight,
            left,
            top,
            type: "popup",
            url: `${process.env.BASE_WEBSITE}/account/login?from=extension&device_id=${device_id}`
        });
    };

    const handleUserLogout = async () => {
        setIsLoggingOut(true);
        const result = await userLogout();
        console.debug("handleUserLogout result", result)
        if (result) {
            sendRuntimeMessage('reset_sync_service');
            window.location.reload();
        } else {
            setIsLoggingOut(false);
        }
    };

    const handleRefreshUserInfo = async () => {
        if (isRefreshing) return;
        setIsRefreshing(true);
        try {
            const freshInfo = await fetchUserInfo();
            setLocalUserInfo(freshInfo);
        } finally {
            setIsRefreshing(false);
        }
    };

    const getMembershipName = () => {
        const { membership } = localUserInfo || {};
        if (membership?.lifetime) return t('lifetimeMembership');
        return membership?.is_member ? t('premium') : t('free');
    };

    const getMembershipExpiryInfo = () => {
        const { membership } = localUserInfo || {};

        if (membership?.is_member) {
            const expiresAt = membership.expires_at;
            const formatDate = (date) => {
                try {
                    return new Date(date).toLocaleDateString(language.replace("_", "-"), { year: 'numeric', month: 'long', day: 'numeric' });
                } catch (error) {
                    console.error('Error formatting date:', error);
                    return date; // Return the original date string if formatting fails
                }
            };

            switch (membership.type) {
                case 'lifetime':
                case 'none':
                case 'subscription':
                default:
                    return "";
                case 'trial':
                    return expiresAt ? t('trialEndsAt', { date: formatDate(expiresAt) }) : "";
                case 'sub_trial':
                    if (membership.subscription_status?.canceled) {
                        // 在试用期，订单取消
                        return membership.subscription_status?.on_grace_period
                            ? (expiresAt ? t('premiumEndsAt', { date: formatDate(expiresAt) }) : "")
                            : (expiresAt ? t('premiumEndsAt', { date: formatDate(expiresAt) }) : "");
                    } else {
                        return expiresAt ? t('trialEndsAndMembershipStarts', { date: formatDate(expiresAt) }) : "";
                    }
                case 'grace':
                case 'fixed':
                    // 订单取消 在宽限期
                    return expiresAt ? t('premiumEndsAt', { date: formatDate(expiresAt) }) : "";
            }
        }
        return '';
    };

    const getPremiumBtn = () => {
        const { membership } = localUserInfo || {};
        const baseWebsite = process.env.BASE_WEBSITE;

        switch (membership?.type) {
            case 'lifetime':
            case 'fixed':
                return { label: t('manageAccount'), link: `${baseWebsite}/account/profile` };
            case 'trial':
            case 'none':
            default:
                return { label: t('subscribePremium'), link: `${baseWebsite}/pricing` };
            case 'sub_trial':
                if (membership.subscription_status?.canceled) {
                    return membership.subscription_status?.on_grace_period
                        ? { label: t('manageSubscription'), link: `${baseWebsite}/account/profile` }
                        : { label: t('subscribePremium'), link: `${baseWebsite}/pricing` };
                } else {
                    return { label: t('manageSubscription'), link: `${baseWebsite}/account/profile` };
                }
            case 'grace':
                return { label: t('manageSubscription'), link: `${baseWebsite}/account/profile` };
            case 'subscription':
                return { label: t('manageSubscription'), link: `${baseWebsite}/account/profile` };
        }
    };

    return (
        <Paper variant='outlined' elevation={0} sx={{ p: 3, borderRadius: 2 }}>
            <Grid container spacing={3} alignItems="center">
                <Grid item xs={12} md={6}>
                    <Box sx={{ display: 'flex', alignItems: 'center', gap: 2 }}>
                        <Avatar sx={{ width: 56, height: 56 }}>
                            <AccountCircleIcon fontSize="large" />
                        </Avatar>
                        <Box>
                            <Box sx={{ display: 'flex', alignItems: 'center', gap: 1 }}>
                                <Typography variant="h3" sx={{ fontWeight: 'bold' }}>
                                    {isLoggedIn ? localUserInfo.email : t('notLoggedIn')}
                                </Typography>
                                {isLoggedIn && (
                                    <IconButton
                                        size="small"
                                        onClick={handleRefreshUserInfo}
                                        disabled={isRefreshing}
                                    >
                                        {isRefreshing ? (
                                            <CircularProgress size={20} />
                                        ) : (
                                            <RefreshIcon fontSize="small" />
                                        )}
                                    </IconButton>
                                )}
                            </Box>
                            {isLoggedIn && (
                                <Box sx={{ mt: 1 }}>
                                    <Box sx={{ display: 'flex', alignItems: 'center', mb: 1 }}>
                                        <Typography
                                            variant="h4"
                                            sx={{ color: 'text.secondary', mr: 1, whiteSpace: 'nowrap' }}
                                        >
                                            {t('currentPlan')}:
                                        </Typography>
                                        <Chip
                                            label={getMembershipName()}
                                            size="small"
                                            color={localUserInfo?.membership?.is_member ? 'primary' : 'default'}
                                            sx={{
                                                p: 0,
                                                color: localUserInfo?.membership?.is_member ? '#FFD700' : '#555',
                                                bgcolor: localUserInfo?.membership?.is_member ? 'default' : '#f0f0f0',
                                                whiteSpace: 'nowrap'
                                            }}
                                        />
                                    </Box>
                                    <Typography
                                        variant="body2"
                                        sx={{ color: 'text.secondary' }}
                                    >
                                        {getMembershipExpiryInfo()}
                                    </Typography>
                                </Box>
                            )}
                        </Box>
                    </Box>
                </Grid>
                <Grid item xs={12} md={6}>
                    <Stack spacing={2} direction="row" justifyContent="flex-end">
                        {isLoggedIn ? (
                            <>
                                {!localUserInfo?.membership?.lifetime && (
                                    <Button
                                        variant="contained"
                                        color="secondary"
                                        startIcon={<CardGiftcardIcon sx={{ color: '#FFD700', animation: 'pulse 1.5s infinite' }} />}
                                        onClick={() => chrome.tabs.create({ url: getPremiumBtn().link, active: true })}
                                        sx={{
                                            borderRadius: 2,
                                            padding: '8px 16px',
                                            textTransform: 'none',
                                            '&:hover': {
                                                backgroundColor: theme => theme.palette.primary.dark,
                                            }
                                        }}
                                    >
                                        {getPremiumBtn().label}
                                    </Button>
                                )}
                                <Button
                                    variant="outlined"
                                    color="secondary"
                                    startIcon={isLoggingOut ? <CircularProgress size={20} color="inherit" /> : <ExitToAppIcon />}
                                    onClick={handleUserLogout}
                                    disabled={isLoggingOut}
                                >
                                    {t('logout')}
                                </Button>
                            </>
                        ) : (
                            <Button
                                variant="contained"
                                color="primary"
                                startIcon={<CardGiftcardIcon sx={{ color: '#FFD700', animation: 'pulse 1.5s infinite' }} />}
                                onClick={handleUserLogin}
                                sx={{
                                    borderRadius: 2,
                                    padding: '8px 16px',
                                    textTransform: 'none',
                                    '&:hover': {
                                        backgroundColor: theme => theme.palette.primary.dark,
                                    }
                                }}
                            >
                                {t('signInForPremium')}
                            </Button>
                        )}
                    </Stack>
                </Grid>
            </Grid>
        </Paper>
    );
};

export default AccountInfo;
