import { SYNC } from '../../../configs/app';
import { recordDebugLog } from '../../../utils/helpers';
import {
    setupWindowTabsTriggers,
    setupRecentClosedTabsTriggers
} from './chromeTriggers';

export function setupTriggers(config, syncCallback) {
    recordDebugLog('[syncService] Setting up triggers...');
    const unsubscribers = new Map();

    if (config.syncMode === SYNC.MODES.DISABLED) {
        recordDebugLog('[syncService] Sync mode is disabled, skipping trigger setup');
        return unsubscribers;
    }

    // Setup window tabs triggers
    if (config.syncDataOptions.windowTabs?.enabled) {
        recordDebugLog('[syncService] Setting up window tabs triggers...');
        const cleanup = setupWindowTabsTriggers(
            () => syncCallback('windowTabs'),
            config.syncDataOptions.windowTabs
        );
        unsubscribers.set('windowTabs', cleanup);
    }

    // Setup recent closed tabs triggers
    if (config.syncDataOptions.recentClosedTabs?.enabled) {
        recordDebugLog('[syncService] Setting up recent closed tabs triggers...');
        const cleanup = setupRecentClosedTabsTriggers(
            () => syncCallback('recentClosedTabs'),
            config.syncDataOptions.recentClosedTabs
        );
        unsubscribers.set('recentClosedTabs', cleanup);
    }

    recordDebugLog('[syncService] Chrome triggers setup complete');
    return unsubscribers;
}

export function cleanupTriggers(unsubscribers) {
    recordDebugLog('[syncService] Cleaning up triggers...');
    unsubscribers.forEach((unsubscribe, key) => {
        recordDebugLog(`[syncService] Unsubscribing from ${key} events`);
        unsubscribe();
    });
    unsubscribers.clear();
    recordDebugLog('[syncService] Trigger cleanup complete');
} 